INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES (5262,3,1,'တစ်ဆယ့်ခြောက်လုံးမြောက်မွန်ဗျည်း။',NULL)
,(5263,3,4,'အန်သည်။','“ဗ္ဂဲတစုတ်လဝ် လ္တူဒကဝ်ရ။” = “ဖျာပေါ်တွင် ကြောင်အန်ထားသည်။”')
,(5263,3,1,'အဖေ၊ ဖခင်။','ယာဲတ = မိဘ။ ‘ဣတ’ ဟု များသောအားဖြင့်ရေးသည်။')
,(5264,3,4,'တွဲလောင်းကျသည်။',NULL)
,(5265,3,1,'လက်ကောက်၊ ခြေချင်းစသည်။','တကံက်တဲထဝ် = ရွှေလက်ကောက်။ || တကံက်ဇိုၚ်သြန် = ငွေခြေချင်း။')
,(5266,3,1,'အနှံ။','တကောင်သြောအ် = စပါးနှံ။ || တကောင်သြောအ်ဂန် = ပြောင်းမွေး။')
,(5267,3,1,'စအို။ ဖင်။ တင်ပါး။',NULL)
,(5268,3,1,'တင်သား။',NULL)
,(5269,3,4,'လန့်သည်။','‘လကိုတ်’ ရှု။')
,(5270,3,1,'ကျွန်း။','တ္ကအ်သိၚ်ဃဵု = သီဟိုဠ်ကျွန်း။ || တ္ကအ်ဇမ္မုဒိပ် = ဇမ္ဗူဒိပ်ကျွန်း။')
,(5271,3,1,'စကြာဝဠာအတွင်း မြင်းမိုရ်တောင်ကို ဗဟိုပြု၍ တည်ရှိသော အရှေ့ကျွန်း','အနောက်ကျွန်း၊ တောင်ကျွန်း၊ မြောက်ကျွန်းဟူသော ကျွန်းကြီးလေးကျွန်း။ (ကျမ်းဂန်လာ)')
,(5272,3,1,'မှီရာကျွန်း။ ခိုလှုံရာ။ အားကိုးရာ။','“တံဒဳပံ၊ န်တကအ်ဗ္ဒ မတွံဂးအရဟတ္တ ဖိုလ်ဂှ်။ ကယိရာထ၊ ဂဗ္ဘသ္ပညိ။” (ဓမ္မပဒ။ ပထမကၞပ်။ ၁၂၉။ ဝါယမထေရ်။) = “အရဟတ္တ ဖိုလ်တည်းဟူသော ခိုလှုံရာမှီရာကျွန်းကို ပြုရာ၏။”')
,(5273,3,1,'မှီရာကျွန်း။ ခိုလှုံရာကျွန်း။ အားကိုးရာ။ အားထားရာ။',NULL)
,(5274,3,1,'စာရေး။','‘စခဳ’||‘ဇခဳ’ ရှု။')
,(5275,3,1,'အပိုင်း။ အခဏ်း။ အပိုင်းအပြတ်။','‘သ္ကုတ်တခန်’ (န||ကြိ)လည်းရှု။')
,(5276,3,5,'အပိုင်းပိုင်း။','သ္ကုတ်ပိုတ်အာတခန်တခန် = အပိုင်းပိုင်းပြတ်သွားသည်။')
,(5277,3,4,'လက်ယပ်သည်။ လက်ယပ်ခေါ်သည်။','“(သၟတ်ဗြဴဂှ်) ဍေံတခါဲ နၚ်တြုံလဗၚ်ဂှ်—။” (ဇ—၆၂။ အစွောံ။) = “သူငယ်မသည် သေသောက်ကြူးကို လက်ယပ်၍ ခေါ်ဆောင်၏။”')
,(5278,3,1,'ခြံဥယျာဉ်တွင်သုံးသော လက်ကိုင်နှင့်ခြစ်။',NULL)
,(5279,3,4,'ရိတ်သည်။ တုံးသည်။','တၚာတ်က္ဍိုပ် = ခေါင်းရိတ်သည်၊ ခေါင်းတုံးသည်။')
,(5280,3,4,'လည်ပင်နင့်သည်။ လည်ချောင်းတွင်ဆို့နင့်သည်။','“အဲစပုၚ်တၚိတ်အာ ဒးသုၚ်ဖျေံဍာ်ရ။” = “ကျွန်တော်ထမင်းစာစဉ် လည်ပင်းနၚ်သွား၍ ရေသောက်ချလိုက်ရသည်။” || တၚိတ်ဍာ် = ရေသောက်စဉ် လည်ချောင်းတွင်ဆို့နင့်သည်။ သီးသည်။')
,(5281,3,4,'ညှစ်သည်။','တၚေတ်ကအ် = လည်ညှစ်သည်။ || တၚေတ်ဍာ်က္ၜဴ = ကြံရည်ညှစ်သည်။ || “သၟတ်တြုံဂှ် ထတ်စောံလောန်၊ ဍေံရပ်တၚေတ်လဝ်အဲ အဲချဳဟွံမာန်ရ။” = “ထိုသူငယ်သည် အလွန်သန်စွမ်းသည်။ ငါ့ကို သူဖမ်းညှစ်ထားရာ ငါမလှုပ်နိုင်ဘဲရှိသည်။”')
,(5282,3,4,'ပုခုံးပေါ်တင်၍သယ်သည်။','“ဗြဴဴအာဟွံမာန်တုဲ ဗောဓိသတ်တၚိန်ကေတ်တုဲ အာတဴရ။” (ဇ—၁၉၃။ အစွောံ။) = “မယားသည် မသွားနိုင်၍ ဘုရားလောင်းသည် ပုခုံးဖြင့် ထမ်းသယ်၍ သွား၏။” || “ဍေံစၚိန်ဖျဴနုၚ်မွဲတုဲ ဍေံကလေၚ်စဴရ။” (ဇ—၂၈၉။ အစွောံ။) = “တခုသောအိုးကိုထမ်း၍ အိမ်သို့ပြန်၏။”')
,(5283,3,4,'ကြိုးစားအားထုတ်သည်။ တက်တက်ကြွကြွရှိသည်။ ထကြွနိုးကြားသည်။','“သွက်ဂွံအာဂှ် ဍေံတ္ၚအ်ဒၟံၚ်ကီုဟာ။” = “သွားရန် သူစိတ်သန်ပါရဲ့လား။” || “ပ္ဍဲမကၠောန်က လောန်သ္ၚိဂှ် မိပိုဲတ္ၚအ်တဴလၟိုန်ရ။” = “ငါတို့အမေသည် အိမ်အလုပ်ကို လုပ်ရာတွင် အမြဲတမ်း တက်တက်ကြွကြွရှိသည်။”')
,(5283,3,9,'(ကြိရှေ့ဆက်) စိတ်ထက်သန်ခြင်း၊ နိုးကြားတက်ကြွခြင်း၊ ပျော်မွေ့ခြင်း၊ ဝါသနာပါခြင်းအနက်ဖြင့် ကြိယာကိုထောက်ပံ့ပေးသော စကားလုံး။','“ဍေံတ္ၚအ် အာဝေၚ်သ္ၚိညးတၞဟ်ရ။” = “သူများအိမ်သို့ သွားလည်ခြင်းဖြင့် သူပျော်မွေ့သည်။” || “ဍေံတ္ၚအ် ဟီုပရောညးတၞဟ်ရ။” = “သူများအကြောင်းပြောရသည်ကို သူဝါသနာပါသည်။” || “မဂဒူဝွံ နွံကဵုဟေန်ဆာဲလွဳပရာ တၚအ် လ္ပအ်သာက္ဍာ တိက်ဂၠုၚုဟ်ပြဟ် ကၠောန်ၜိုတ်ဒုၚ်ကာသၟိၚ်ဗ္တံတ္ၚဲရ။” = “မဂဒူးသည် ခြိုးခြံသောအ ကျင့်ရှိ၍ တက်ကြွဖျတ်လတ်ကာ နောက်မှအိပ်ပြီး စောစီးစွာနိုး၏၊ နေ့ညမဟူ ကြိုးစားအား ထုတ်၍ မင်းအမှုထမ်း၏။”')
,(5285,3,4,'လွဲချော်သည်။ ချွတ်ချော်သည်။ ချွတ်ယွင်းသည်။','“သၟိၚ်ကုသယိုက်ကေတ်ဒလေၚ်ပုၚ်ဂှ်တုဲ ကွာ်တိတ်အာတုဲ ပ္ဍဲဂၠးပါၚ်တရၚ်ပြာသာဒ်ပြဘာဝတဳဂှ် ညံၚ်ဇိုၚ်မတဆူလောတ်အာဂှ်ပတုဲ ထ မာဲပုၚ်သွတံဂှ် လောတၟဝ်အာရ။” (ဇ—၅၃၁။ အစွောံ။) = “ကုသမင်းသည် ထမင်းထမ်းပိုးကို ထမ်း၍ ထွက်ခဲ့သည်ရှိသော် ပဘာဝတီတိုက်ခန်းတံခါးအနီး ပြာသာဒ်အပြင်­ ခြေချော်လဲသကဲ့ သို့ပြု၍ ထမင်းဟင်းအိုးခွက်တို့သည် လိမ့်ကုန်၏။” || “ညံၚ်ဇၟူတၠအစောံ ဟွံပ္တေဟ်ဇိုၚ်ပန်တုဲ နလပှ်ဖျောန်ဏာဂတ စံၜတ်တုဲမကွာ်ဂး ဇၟူဂှ် ဟွံသလိုၚ်ဟွံတဆူရောၚ်။” (ဇ—ဝိဓုရ။ အစွောံ။) = “အစွမ်းအားရှင်ဖြစ်သော ဆင်ပြောင်ကြီးသည် အခြေလေးချောင်းတို့ကို မယုံမူ၍ နှာမောင်းရှေ့သွား လမ်းညွှန်ပြုခြင်းအားဖြင့် တိုင်းထွာစမ်းသပ်၍ လျှောက်သဖြင့် ကျွံခြင်း၊ ချွတ်ချော်တိမ်းပါး ခြင်း မရှိသည်ဖြစ်၏။”')
,(5286,3,4,'ချွတ်ယွင်းစွာပြောမိသည်။ ဆိုလိုသည်ကတစ်မျိုး ပြောမိသည်ကတစ်ခြားဖြစ်သည်။','“ၜိုန်မဇကုဟီုတဆူအာကီုလေဝ် ဗောဓိသတ်တၠညာန် ဂြၚ်ဗက်လဟီုသၟိၚ်ဂှ်ဂတာပ်တုဲ ဂွံပခိုၚ် ပ္တိုန်ဂလာန်မဇကုရ။”(ဇ—၂၁၁။ အစွောံ။) = “မိမိဖခင်ချွတ်ယွင်း၍ ဆိုမိသော်ငြားလည်း ဉာဏ်ရှင်ဘုရားလောင်းသည် မင်း၏စကားကို လျင်စွာသိလိုက်သဖြင့် ဖခင်၏စကားကို ခိုၚ်အောင်ပြင် ပြောပေးနိုင်ခဲ့၏။”')
,(5287,3,4,'ယိမ်းယိုၚ်သည်။ တိမ်းစောင်းသည်။','‘ဆူဒလူ’ ရှု။')
,(5288,3,4,'‘ကဆံ’ ရှု။',NULL)
,(5289,3,1,'ကချေသည်။',NULL)
,(5290,3,4,'နောက်သို့ဆုတ်သည်။ ဆုတ်နစ်သည်။ (ပါဠိ—သြသက္ကတိ)','“စိၚ်ဂှ် အာရဂးကဵုဍေံဂှ် ဍေံတဆုတ်ကၠေံရ။ တဆုတ်ရဂးကဵုဍေံဂှ် ဍေံအာကၠေံဗွဲဂတရ။” (ဇ—၂၃၁။ အစွောံ) = “ထိုဆင်သည် သွားလော့ဟုဆိုသည်ရှိသော် နောက်သို့ဆုတ်၏။ နောက်သို့ဆုတ်လော့ဟု ဆိုသည်ရှိသော် ရှေ့သို့ပြေး၏။” (ညောင်ကန်) || ‘ဆုတ်’ (ကြိ—၂) နှင့်အတူတူ။')
,(5291,3,4,'ခြေကိုထောက်၍ထောက်၍ ဟန်ပါပါလျှောက်သည်။','“တီဒဒှ်စိၚ်ချိုတ်တုဲ ဂစေံတၞောတ်ဗြဴမိပ်စိုတ်တုဲ ထဏိက်တဆန် လတူက္ဍိုပ်စိၚ်ဂှ်ရ။” (ဇ—၃၅၇။ အစွောံ။) = “ဆင် သေကြောင်းကိုသိ၍ နှံစုတ်ငှက်ငယ်မသည် ဝမ်းမြောက်၍ ဆင်ဦးခေါင်းထက်­ ကန်ကျောက် လျက် ဟန်ပါပါလျှောက်၏။” || ‘ကွာ်တဆန်’ လည်းရှု။')
,(5292,3,1,'တံဆိပ်။ လက်တံဆိပ်။','တက်တဆိပ် = တံဆိပ်ခတ်သည်။ || “သာ်ဝွံကှ်ေလိက်တုဲ နတဆိပ်သေဋ္ဌဳဟေၚ်တက်တုဲ—။” (ဇ—၁၂၅။ အစွောံ။) = “ဤကဲ့သို့စာရေး၍ သူဌေးတံဆိပ်ခတ်၍—။” || “လိက်ဂှ်ကီု ဖျုန်ခဍာ်ဂှ်ကီု ဂွဳထုပ်ကဵုယာတ်ဗတာၚ်တုဲ နတဆိပ်တဲသၟိၚ်တက်တုဲ အဲကဵုပလံၚ်ဏာညိ။” (ဇ—၂၁၄။ အစွောံ။) = “စာခွေကို၄င်း ကျီးသားကို ၄င်းပုဝါဖြူဖြင့်ထုပ်၍ မင်း၏ (လက်) တံဆိပ်ဖြင့်ခတ်၍ ပို့စေအံ့။” (ညောင်ကန်) || “ဗောဓိသတ်ရံၚ်တုဲ ဒှ်ထိုၚ်ဖျေဲဒဆိပ်တဲဇကုတီတုဲ—။” (ဇ—၂၈၈။ အစွောံ။) = “ဘုရားလောင်းသည် (ကြည့်သည်ရှိသော်) မိမိ၏တံဆိပ်ကိုမြင်၍ မိမိဥစ္စာအဖြစ်ကို သိ၍—။” (ညောင်ကန်)')
,(5293,3,1,'ဘွဲ့။ ဘွဲ့တံဆိပ်။','“သဳလဝန္တ၊ နာမခုတ်လဝ်။ အဂ္ဂမဟာ၊ ပဏ္ဍိတာဓဝ်။ သၟိၚ်ဇိုန် ကဵုကၠာ၊ တဆိပ်ကြာထဝ်။” (ပြကိုဟ်ဓမ္မရာသဳ။ သဳလဝန္တထေရ် / မာံရွှေငိုး။) = “သဳလဝန္တဟု အမည်တွင်သော အကျွန်ုပ်အား ဗုဒ္ဓတရားဓမ္မဆိုင်ရာ အဂ္ဂမဟာပဏ္ဍိတ ရွှေဘွဲ့တံဆိပ်ကို အစိုးရမှ ဆက်ကပ်ချီးမြှင့်ပါသည်။”')
,(5294,3,4,'ချောသည်။ လျှောသည်။','တဆေဝ်စှ်ေ = ချောကျသည်။ လျှောကျသည်။ || “ဍေံရပ်ဒုန်တၞုၚ်ဂှ်တုဲ တဆေဝ်စှ်ေကၠုၚ်နူတၞံဆုရ။” = “ဝါးချောင်းကိုကိုင်ပြီး သစ်ပင်ပေါ်မှ သူ လျှောဆင်းသည်။”')
,(5295,3,1,'နွေရာသီ။',NULL)
,(5296,3,4,'တိမ်သည်။','‘က္ဍာ’ ရှု။')
,(5297,3,4,'စိုစွတ်သည်။','‘ဍေက်’ ရှု။')
,(5298,3,4,'စိုရွှဲသည်။ ရွှဲရွှဲစိုသည်။ ရေစက်ရေပေါက်တို့ဖြင့် ယိုစီးလျက်ရှိသည်။','“သီု ဍာ်သၠိုက်မတဍေက်ဇွောဝ်ဒၟံၚ် မကၠုၚ်ဝွံဂှ် ပ္ဍဲဒေါဝ်တြဴ ဗြဲဗ္ဂူဟာ။” (ဇ—၁။ အစွောံ။) = “ညွန်ဖြင့်လိမ်းကျံကုန်သည်ဖြစ်၍ ယိုစီးကုန်သောရေပေါက်တို့ဖြင့် လာကုန်၏၊ သင်တို့လာသောခရီး­ မိုးရွာသလော။”')
,(5299,3,4,'‘တဍေက်ဇွောဝ်’ နှင့်အတူတူ။','“သီုကဵုလှိုက်သရီု မတဍေက်ဒဇက်တဴ ဍေံမကၠုၚ်။” (ဇ—၁။ အစွောံ။) = “ညွန်တို့ဖြင့်လိမ်းကျံကုန်လျက် ယိုသောရေပေါက်ရှိကုန်သည်ဖြစ်၍ လာကြကုန်၏။”')
,(5300,3,4,'စိတ်နောက်ကျုသည်။ မတည်မငြိမ်ဖြစ်သည်။ စိတ်အနှောက်အရှက်ဖြစ်သည်။','“ပတွဵုနူမဒှ်တၠဂယိုၚ်တုဲ စိုတ်အဲဍိက်တဍိုက်လ္ၚေၚ်အာတုဲ ကွတ်ဗိုတ်တံ ဟွံဂွံလ္ၚတ်တိုန်ပါၚ်ရအဴ” ဗမၞးဂး။ (ဇ—၁၈၅။ အစွောံ။) = “အကျွန်ုပ်သည် အိမ်ထောင်ပြုသည်မှစ၍ နောက်ကျုသော စိတ်ရှိသည်ဖြစ်၍ ဗေဒင်အတတ်တို့သည် နှုတ်မတက်တော့။” || “ပ္ဍဲကာလကြဴဝွံ ဗမၞးဂိုၚ်ကေတ် ဒတဴသ္ၚိကၟိန်တုဲ ဟိုတ်နူမချပ်တဴကေၚ်ကာသ္ၚိကၟိန်ဂှ်တုဲ စိုတ်တဍိုက်လ္ၚေၚ်အာ။” (ဇ—၁၈၅။ အစွောံ။) = “ထိုပုဏ္ဏားသည် နောင်အခါ­ အိမ်ထောင်ခြင်းကိုပြု၍ အိမ်ထောင်မှုကိုကြံသဖြင့် နောက်ကျုသောစိတ်ရှိသည်ဖြစ်၍—။” (ညောင်ကန်) || ‘ကၠိုက်လ္ၚေၚ်’ လည်းရှု။')
,(5301,3,1,'အထူ။ အစိုင်အခဲ။ တစ်ခဲနက်ထူထဲသောအရာ။','“ဟာဲကၠိက်တံ၊ ဂေါဟ်မၞိက်ဝွံဂှ် ဍေံမတၟုဲတဴနမၞိက်ဝေလုရောၚ်။ ဍေံမၞုံကဵုတဍတ်မသတီု ဍေံမဇၞော်လောန် ဍေံဆာဲလောန်၊ တၞဟ်နပၠေၚ် ကၠေံလျးကျာ်သြဳမၞိက်ဂှ် မၞးတံဟွံသၟဟ်ရထရ။” (ဇ—၂၈၅။ အစွောံ။) = “ဟယ်ဝက်တို့၊ ဤပတ္တမြားလိုဏ်သည် ကြောင်မျက်ရွဲဖြင့်ပြီး၏။ တစ်ခဲနက်သောအထူရှိ၏၊ အလွန်ကြီး၏၊ အလွန်တင့်တယ်၏။ ဤပတ္တမြား၏အရောင်အဝါကို သင်တို့ဖျောက်အံ့သောငှာ မတတ်ကောင်း။”')
,(5301,3,3,'တစ်ခဲနက်ထူထဲသော။ ခိုင်ခံ့ထူထဲသော။ တစ်လုံးတစ်ခဲသော။ အခေါင်းအပေါက်မရှိသော။','(ပါဠိ—ဃန) “ဃနပုပ္ဖကော။ ဍေံမၞုံဍောၚ်ပ္ကဴတဍတ်တဴ။ ဝါ။ ဍေံမၞုံပ္ကဴတၟုတ်မသတီု။” (တြာဲဝိနယ သၚ်ရိုဟ်ဂြဳ။ ဒု။ ၅၃၉။ စန္ဒိမာမဟာထေရ်။) = “တစ်ခဲနက်သော ပန်းပြောက်အတိရှိသော။”')
,(5302,3,1,'သစ်ပင်ချုံနွယ်များ ထူထဲစွာပေါက်ရောက်၍ သွားလာရန်ခဲယဉ်းသောတောအုပ်။','“ဗောဓိသတ်ဒှ်ပြေၚ် ပ္ဍဲဂြိုပ်ဟေမဝန် — ပ္ဍဲဇရေၚ်လဂေါဝ်ဇိုၚ်တၟံ တဍတ်ဂြိုပ်မွဲဂှ် ဂ္ၚေၚ်စရ။” (ဇ—၂၇၈။ အစွောံ။) = “ဘုရားလောင်းသည် ဟိမဝန္တာအရပ်ဝယ် ကျွဲမျိုး­ဖြစ်၍ — တောင်ခြေရင်း ချိုင့်ဝှမ်းရာ ခဲယဉ်းသောတောအုပ်တို့­ ကျက်စားလျက်—။” (ညောင်ကန်)')
,(5303,3,1,'ကျောက်တောင်။ ကျောက်သားအတိပြီးသောတောင်။',NULL)
,(5304,3,1,'စည်း။ (တူရိယာပစ္စည်း)',NULL)
,(5305,3,1,'မနေ့ကအလျင်ဖြစ်သောနေ့။ မနေ့ကမတိုင်မီတစ်နေ့။',NULL)
,(5306,3,4,'လိမ်လည်သည်။ ထိမ်ချန်သည်။','‘တနိက်’ ရှု။')
,(5307,3,4,'‘တၞၚ်လ္ဂုၚ်’ ရှု။',NULL)
,(5308,3,1,'အပ်။',NULL)
,(5309,3,1,'‘ကၞုၚ်’ ရှု။',NULL)
,(5310,3,1,'လှေခါး။','က္ဍိုပ်တၞိန် = လှေခါးထိပ်။ || ဇိုၚ်တၞိန် = လှေခါးရင်း။')
,(5311,3,1,'ပန်းဆွဲ။','“(ကလော်ဗြဴတံဂှ်) ဍေံက္တဵုဗဒှ်လဝ်ဇြပ်ဇၞူမွဲတုဲ သီုတရိုန်တဏာဲထဝ်မစိစောန် လးလဝ်သၞာစဵုဇၞိက်တုဲ—။” (ဇ—၉၆။ အစွောံ။) = “ဘီလူးမတို့သည် ဆန်းကြယ်စွာသော တုရိုဏ်တိုင်နှင့်တကွ ရွှေပန်းဆွဲပါသော တည်းခိုရန်ဇရပ်တစ်ခုကို ဖန်ဆင်း၍ အိပ်ရာနေရာခင်းထားကာ တင်းတိမ်ကာရံထားကုန်၏။”')
,(5312,3,1,'ခြတောင်ပို့။',NULL)
,(5313,3,1,'မနေ့။ ယမန်နေ့။','ပ္ဍဲတၞေံတေံဂှ် (ဇ—၂၂၈။ အစွောံ။) = ယမန်နေ့က။ (ညောင်ကန်) || “တၠတအ်ကၠုၚ်စိုပ်လၟုဟ်ဟာ” ကျာ်တြဲသၟာန်။ “ယွံတဳလမၞုံပိုန်၊ ပိုဲဍိက်စိုပ်နူတ ဏေအ်ရအဴ။ တဏေအ်ဝွံဂှ် တ္ၚဲဂၠုအာတုဲ ကၠုၚ်သဳကၠဳတဳလမၞုံပိုန်ဟွံဂတာပ်တုဲ တ္ၚဲဝွံကၠုၚ်သဳကၠဳကျာ် တြဲရောၚ်အဴ” ခမဳဂှ်ဂး။ (ဇ—၃၁၂။ အစွောံ။) = “သင်တို့ယခုမှရောက်သလော” ဟုမြတ်စွာဘုရား မေးတော်မူ၏။ “အရှင်ဘုရား၊ တပည့်တော်တို့ မနေ့ကတည်းက ရောက်ပါ၏။ မနေ့က မိုးချုပ်သွားသဖြင့် အရှင်ဘုရားအား ဖူးမြင်ရန်မမီသောကြောင့် ယနေ့မှလာဖူးမြင်ရပါ၏” ဟု ထိုရဟန်းဆို၏။')
,(5314,3,1,'မကြာသေးခင်ကာလ။ မနေ့တစ်နေ့။','“တဏေအ်တဏိဏအ်ရ ဗှ်ေဂွံဒှ်ကၠုၚ်မၞိဟ်၊ ဗှ်ေလ္ပကၠုၚ်ပဒၟံၚ်အ္စာကဵုအဲညိ။” = “မနေ့တစ်နေ့ကမှ နၚ်လူဖြစ်လာတယ်၊ ငါ့ကို ဆရာလာမလုပ်နေနဲ့။”')
,(5315,3,5,'မတောက်တခေါက်။ နှံ့စပ်ကျွမ်းကျင်ခြင်းမရှိဘဲ။','“လေပ်လဝ်လိက်မန် တတတံၚ်တံၚ်တုဲ ပဒၟံၚ်ညးမဒါန်လိက်ပရိုၚ်မန်ဟာ။” = “မွန်စာကို မတောက်တခေါက်တတ်ထားပြီး မွန်သတင်းစာအယ်ဒီတာလုပ်နေသလား။”')
,(5316,3,10,'(နဝိ) တတိယ။',NULL)
,(5317,3,1,'သပေါ့ဖျာ။ သင်ဖြူး။ (ပါဠိ—တဋ္ဋိကာ)','‘ကဲလာ’ နှင့်အတူတူ။')
,(5318,3,10,'(န) တဒၚ်္ဂ။ တစ်ခဏ။','“ယဝ်ရကလိဂွံဒုၚ်စသိုၚ် ရှ်ဓဝ်တဳလမၞုံကုပိုန်ကျာ်တြဲ အယာံမာတ်မွဲတဒၚ်္ဂခဏဂှ် မဂွံတိတ်ဗၠးအာနူဘုံပိတုဲ မဂွံအာစိုပ်နိဗ္ဗာန်မာန်ရောၚ်။” (သၚ်္ခါရဘေဒနဳ||ဝိန္ဒသာရ) = “မြတ်စွာဘုရားတရားတော်၏ အမြိုက်အရသာကို တဒၚ်္ဂတစ်ခဏတာမျှ ရရှိခံစားလျှင် ဘုံသုံးပါးမှလွတ်မြောက်၍ နိဗ္ဗာန်သို့ရောက်ရှိနိုင်၏။”')
,(5319,3,4,'လိမ်လည်သည်။ ထိမ်ချန်သည်။ ထိမ်ဝှက်သည်။','“ယြဴပူဂဵုမွဲ ပွယုတ်မာတုဲ အဲဟွံဂွံပဂးတုဲ မဒးတဏိက်လဝ်ဂှ် ပူဂဵုဂှ် မသက္ကုဒတုဲမြမောဝ်ဂှ် မဒးဒှ်ရ။” (ဇ— ၂၈၅။ အစွောံ။) = “အကြင်သူသည် ယုတ်မာသောအမှုကိုပြု၍ ငါမပြုရပါဟုဆို၍ ထိမ်ဝှက်၏၊ ထိုသူသည် အကျိုးမဲ့သာဖြစ်ရာ၏။”')
,(5320,3,4,'လိမ်လည်ထိမ်ဝှက်သည်။ မဟုတ်မမှန်ပြောဆိုသည်။ မုသားဆိုသည်။','“ယွံဗမၞး၊ မန်ဝွံ အနဂ္ဃမန်ရောၚ်။ နိသြဲကဵုမန်ဝွံတုဲ ဒြပ်ဂၠိုၚ်ကလိဂွံရ။ ခါရညးသၟာန် ဂလာန်တနိက်တလန် လ္ပပညိ။ မန်ဝွံ အဲကတ်ကေတ်ဇရေၚ်စဏာရောၚ် မၞးဂးညိ။—။” (ဇ—၄၇၄။ အစွောံ။) = “ပုဏ္ဏား၊ ဤမန္တန်သည် အဖိုးအနဂ္ဃထိုက်သောမန္တန်တည်း။ ဤမန္တန်ကိုမှီ၍ များစွာသောဥစ္စာကို ရလတ္တံ့။ တစ်စုံတစ်ယောက်မေးသည်ရှိသော် ထိမ်ဝှက်၍ မုသားကိုမဆိုလင့်။ ဒွန်းစဏ္ဍား (သူတောင်းစား) အထံမှ သင်ယူရရှိ၏ဟု (အမှန်ကို) သင်ဆိုလေလော့။” || “ယြဴသုရာမွဲဂှ် ညးသုၚ်ဍေံတုဲ ဂလာန်မုသာတနိက်တလန်ဂှ် မဒးဟီုကဵုညးရ။” (ဇ—၅၁၂။ အစွောံ။) = “သေရည်အရက်မည်သည်ကို သောက်သုံးသောသူသည် သူတစ်ပါးအား လိမ်လည်သောမုသားစကားကို ပြောဆိုမိရာ၏။”')
,(5321,3,1,'??','“ဗဗေၚ်မပ္ၚာလဝ် ပ္ဍဲတနာၚ်မၞုံကဵုဒစဵုဝုတ်ဒိုဟ်တုန်။ သီုလျိုၚ်လေဝ် စွံပ္ဍဲတနာၚ်ဂွံရ။ လမ္ၚုလေဝ် စွံလဝ်ပ္ဍဲတနာၚ်ဂွံရ။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ ဒု။ ၅ဝ၉။ စန္ဒိမာမဟာထေရ်။)')
,(5322,3,1,'‘တၞအ်မတ်’ ရှု။',NULL)
,(5323,3,4,'ချသည်။ စွန့်ချသည်။ ပစ်ချသည်။','“သတ်နရက်ဂှ် ခုရစက်ဍေံမဒးယဵုလဝ်ဂှ် ဍေံတဖဝ်စုတ် ပ္ဍဲက္ဍိုပ်မၚ်ဗၠာဲမိတ္တဝိန္ဒကတုဲ ဝဳပက်ဍေံအိုတ် ဍေံအာကၠေံရ။” (ဇ—၁ဝ၄။ အစွောံ။) = “သင်ဓုန်းစက်ရွက်သော ငရဲသားသည် ထိုသင်ဓုန်းစက်ကို မိတ္တဝိန္ဒကလုလင်၏ ဦးခေါင်း­စွန့်ချပြီးလျှင် ဝိပက်ဝဋ်ကြွေးကုန်သည်ဖြစ်၍ ဖဲခွာသွား၏။”')
,(5323,3,4,'ချသည်။ စွန့်ချသည်။ ပစ်ချသည်။','‘လဖဝ်’ ရှု။')
,(5324,3,1,'‘တၟာ’ ရှု။',NULL)
,(5325,3,4,'တွက်ချက်သည်။',NULL)
,(5325,3,1,'အတွက်အချက်။ တွက်ချက်ခြင်း။',NULL)
,(5326,3,4,'တွက်ကပ်သည်။','“ကောန်ဝုတ်ပိုဲၜါဂှ် ကၠောန်ကလောန်ညဳသာညးသ္ကံလၟိုန် ညးမွဲကဵုညးမွဲ ဟွံတၟော်စမွဲလှ်ေရ။” = “ငါတို့သမီးပျိုနှစ်ယောက်တို့သည် အလုပ်လုပ်ရာတွင် အ မြဲတမ်းညီညွတ်ကြသည်။ အချင်းချင်း တစ်ခါမျှ မတွက်ကပ်ကြပါ။”')
,(5327,3,1,'ခြေ­ခတ်သောကြိုး။ သံကွင်း။ ထူး။ (ပါဠိ—နိဂဠ)','တမာၚ်စိၚ် = ဆင်ချည် သံကွင်း။ ဆင်ထူး။ (ပါဠိ—အန္ဒုက) || ဇုက်တမာၚ်ဂၠဴ = နွားချည်ကြိုး။ (ပါဠိ—ဒါမ) || ‘ကၟာၚ်’ ဟုလည်းရေးသည်။')
,(5328,3,4,'သာယာစွာတွန်ကျူးသည်။','“သတ်တၠသၞေၚ်ဂစေံဂမၠိုၚ် မၞုံကဵုဗရုတွိၚ်ဂရဴ အဝ်ဇ မဂၠိုၚ်ကဵုသာ် မဗြုမတမှိၚ်တမှဴတဴရ။” (ဇ—၅၃၆။ အစွောံ။) = “ကျေးငှက်သာရကာများသည် အထူးထူးအပြားပြားသော တူရိယာသံကဲ့သို့ သာယာနာပျော်ဖွယ်သော တွန်ကျူးသံတို့ဖြင့် သာယာစွာတွန်ကျူးကြကုန်၏။”')
,(5329,3,1,'ကပြင်။ အိမ်ကပြင်။',NULL)
,(5330,3,1,'အမောအပန်း။ မောပန်းခြင်း။','“ဒေံအဲသၟတ်ၜါဝွံဂှ် ကၠုၚ်စိုပ်နူဂြိုပ်သီုတ မောၚ်ဂှ် မိၚ်ပရိုၚ်သၟိၚ်မစုတိအာဗက်ဂှ် ဖျုန်ဂြိုဟ်မဒကးအာရ။” (ဇ—၄၆၁။ အစွောံ။) = “ငါ့ညီ ငယ်နှစ်ယောက်တို့သည် အမောအပန်းဖြင့် တောမှပြန်ရောက်လာ၍ ခမည်းတော်မင်းကြီးသေလွန်သော သတင်းကိုကြားသည်ရှိသော် နှလုံးကွဲလေရာ၏။” || “ဣသိဗြဴမယဲဂှ်တုန် တမောၚ်ဂှ်ဂၠိုၚ် တိုန်တုဲ ကၠာနူဗောဓိသတ်ဟွံစိုပ်ဂှ် ဣသိဗြဴလမျီုအိုတ်အာ ပကာဂစိုတ်ရ။” (ဇ—၃၂၈။ အစွောံ။) = “ဖျားနာသောရသေ့မသည် အမောဆို့လာ၍ ဘုရားလောင်းမရောက်လာမီ အသက်ကုန်၍ဆုံး လေ၏။” || ပ္တန်တမောၚ်၊ ပ္တေဝ်တမောၚ် = အမောဖြေသည်။ အပင်ပန်းဖြေသည်။ || တၟောၚ်တန်၊ တၟောၚ်တေဝ်၊ တၟောၚ်ဟဲ = အမောပြေသည်။ အမောအပန်းပြေသည်။ || ‘လမောၚ်’/‘လၟောၚ်’ နှင့်အတူတူ။ || ‘ဍောၚ်’ (ကြိ) လည်းရှု။')
,(5331,3,1,'စိတ်မောခြင်း။ စိတ်ပင်ပန်းခြင်း။ စိတ်ဆင်းရဲခြင်း။','ဒှ်တၟောၚ်စိုတ် = စိတ်မောသည်။ စိတ်ပင်ပန်းသည်။ စိတ်ဆင်းရဲသည်။ || “ကောန်သမၠီုတံဂှ် က္တဵုဗဒှ်တဴတမောၚ် စိုတ်မိမလၟိုန်ရ။” = “မိုက်မဲသောသားသမီးတို့သည် မိဘစိတ်ပင်ပန်းအောင် အမြဲပြုနေသည်။” ||  ‘လၟောၚ်စိုတ်’ နှင့်အတူတူ။')
,(5332,3,1,'အမောအပန်း။ မောပန်းခြင်း။ ပင်ပန်းခြင်း။ ဆင်းရဲခြင်း။','“ကုဋဳပဏ္ဏသာ အဲမကနှံလဝ် သီုတၟောၚ်တၟိတ်ဂှ် ပၟတ်စံၚ်ပၠေၚ်ကၠေံဖအိုတ်ရသွံ” ဣသိဂး။ (ဇ— ၁၆၂။ အစွောံ။) = “အပင်ပန်းခံ၍ ငါဆောက်လုပ်ထားသော ကျောင်းသၚ်္ခမ်းကို မီးသည် လောၚ်မြိုက်ဖျက်ဆီးလိုက်ကုန်ပြီတကား” ဟုရသေ့ဆို၏။ || ‘လမောၚ်လမိတ်’/‘လၟောၚ်လၟိတ်’(န) နှင့်အတူတူ။ || ‘ဍောၚ်ၜိုတ်’ (ကြိ) လည်းရှု။')
,(5333,3,4,'အမောပြေသည်။ အပန်းပြေသည်။','“ဗောဓိသတ်ဖုံဍာ်ကဵုမရ။ ဆိုန်ပတ်ဇိုၚ်ပတ်စးတုဲ စုတ်ပၟတ်ပယေဝ် ကဵုဖအၚ်ဇိုၚ်တဲ ကဵုဖအၚ်ဇကုတုဲ တၟောၚ်တန်မဇကုညိတုဲ ရဴဝွံဗောဓိသတ်သ္ဂးကဵုမရ။” (ဇ—၃၁၂။ အစွောံ။) = “ဘုရားလောင်းသည် အဘကို ရေချိုးစေ၍ ခြေနှင့်ကျောက်ကို ဆုပ်နယ်ပေး၍ မီးအိုးကင်းကိုထည့်၍ မီးလှုံစေ၏၊ အဘအမောပြေသောအခါ အဘကို ဤသို့ဆို၏။”')
,(5334,3,4,'အမောပြေသည်။ အပန်းပြေသည်။','“သၟိၚ်သီုမဍောၚ်ၜိုတ်ဂှ်ဒှ် တုဲ ပ္ဍဲထဝဲါသၟတ်ဗြဴဂှ် သတိက်ဒၟံၚ်မွဲချိုန်တုဲ တၟောၚ်တေဝ်တုဲ သၟတ်ဗြဴဂှ် ပ္တိုန်ပ္ဍိုက်ချေံတုဲ လုပ်အာ ဍုၚ်ရ။” (ဇ—၄၁၅။ အစွောံ။) = “မင်းသည် မောပန်းသည်ဖြစ်၍ မိန်းမပျို၏ပေါင်ပေါ်တွင် တခဏအိပ်၍ အမောပြေလတ်သော် မိန်းမပျိုကို မြင်းပေါ်တင်ကာစီးစေ၍ မြို့သို့ဝင်၏။” || “စိုပ်ဒေါဝ်တရဴ ပ္ဍဲဇရေၚ်တၞံဇြဲသုံမွဲဂှ် သၟိၚ်လုပ်ဇူဒၟံၚ်ရ။ တၟောၚ်ပ္တေဝ်ညိတုဲ ပ္ဍဲသၟိၚ်မက္တဵုအာဂှ် ကလော်ရပ် ကေတ်သၟိၚ်ရ။” (ဇ—၃၉၈။ အစွောံ။) = “မင်းသည် ခရီးလမ်းခုလတ်ရှိ တစ်ခုသောပညောင်ပင် ဝင်နားနေ၏။ အနည်းငယ်အမောပြေ၍ ထ၍သွားစဉ် မင်းအား ဘီလူးကဖမ်းယူလေ၏။”')
,(5335,3,4,'အမောပြေသည်။ အပန်းပြေသည်။ အမောအပန်းငြိမ်းသည်။','“ၝောံသ္တိက်ဒၟံၚ် ပ္တေဝ်တမောၚ်ညိကၠာရ။ အဲအာဂ္ၚေၚ်ပိဏ္ဍပါတ်ညိကၠာ၊ ဂွံပိဏ္ဍပါတ်တုဲ ၝောံဂွံယိုပ်ယာပ် ပိဏ္ဍပါတ်ညိတုဲ ကာလဂှ် တမောၚ်ဂွံဟဲတုဲ ဒြဟတ်ဂွံတိုန်ရောၚ်” ဣသိဂးကဵုဣသိဗြဴရ။ (ဇ— ၃၂၈။ အစွောံ။) = “ရှင်မ၊ အိပ်နေ၍ အမောဖြေပါဦး။ ငါဆွမ်းခံသွားအံ့၊ ဆွမ်းကိုရ၍ ရှင်မ၊ သုံးဆောင်ရသောအခါ အမောအပန်းငြိမ်း၍ ခွန်အားတက်လာလတ္တံ့။”')
,(5336,3,4,'(သစ်ပင်) အမြစ်လှန်ခုတ်လှဲသည်။ အမြစ်လန်စေသည်။','‘ကၟိုၚ်’ ရှု။')
,(5337,3,1,'အတွေ့။ အထိအတွေ့။','“ပ္ကဴဒကှ်မ္ဂးဂှ် ဍေံမဒှ်ပ္ဍဲဍာ် ဍေံမဒွအ်တၟတ်လျးတ္ၚဲတုဲ ဍေံမပံက်ထာၚ်။” (ဇ—၃၉၆။ အစွောံ။) = “ကြာပန်းမည်သည် ရေ­ဖြစ်၍ နေရောင်ခြည်အတွေ့ကို ထိတွေ့၍ ပွင့်လာသည်။” || “သၟတ်ဗြဴမွဲ ဒၞာဲတမတ်တဲမဍိုန် မတုပ်ညံၚ်တဲအဲဂှ်မွဲ။”(ဇ— ၂၆၂။ အစွောံ။) = “ငါ့လက်ကဲ့သို့ နူးညံ့သောလက်အတွေ့ရှိသော မိန်းမပျိုတစ်ယောက်သည်လည်း အကြောင်းတစ်ပါး။” || “ဒးတမတ်တဲဒိပ်ဗြဴအဆေဝ်သွဝ်ဂှ်တုဲ ဣသိသိၚ်္ဂဂှ် လှိၚ်အာဗၞတ် ပိသၞာံဟေၚ်ရ။” (ဇ—၅၂၃။ အစွောံ။) = “နတ်သမီး၏ နတ်လက်အထိအတွေ့ကို ထိတွေ့သည် ရှိသော် ဣသိသိၚ်္ဂရသေ့သည် သုံးနှစ်မျှ အိပ်ပျော်သွားလေ၏။” || “နတဲသၟိၚ်ဣန် မဒှ်တၟတ်ဒိပ်ဂှ် ဇွိတ်သ္ပောတ်ဂၞကျာ်တုဲ ဂၞကျာ်လှိၚ်အာရ။” (ဇ—၅၃၁။ အစွောံ။) = “နတ်၏အထိအတွေ့ဖြစ်သော သိကြားမင်းလက်ဖြင့် မိဖုရားအားပွတ်သပ်၍ မိဖုရားအိပ်ပျော်သွားလေ၏။” (မှတ်ချက်။ ‘ဒိပ်’သည် ပါဠိဝေါဟာရ ‘ဒိဗ္ဗ’ မှ ဆင်းသက်လာသည်။ ‘နတ်­ဖြစ်သော/နတ်နှင့်ဆိုင်သော’ ဟုအနက်ရသည်။ ‘တမတ်ဒိပ်’ ဟူသည်မှာ ‘နတ်­ဖြစ်သောအထိအတွေ့/နတ်၏အထိအတွေ့’ ဟု အဓိပ္ပါယ်ရသည်။) || “သၟတ်ကောန်သၟိၚ်ဂှ် တြုံတံဂှ်ဟေၚ် မဂွံဥပ္ပကာရ။ ရုပ်ဗြဴကီု ရမျှာၚ်ဗြဴ ကီု တမတ်ဇကုဗြဴကီု ဟွံဒးဂၞပ်သက်သက်ရ။” (ဇ—၂၆၃။ အစွောံ။) = “ထိုမင်းသားငယ်အား ယောကျာ်းတို့သာလျှင် ပြုစုရ၏။ မင်းသားငယ်သည် မိန်းမရုပ်ကို၄င်း မိန်းမအသံကို၄င်း မိန်းမကိုယ်အထိအတွေ့ကို၄င်း လုံးဝမနှစ်သက်။”')
,(5337,3,4,'ထိတွေ့သည်။ သုံးသပ်သည်။','“ယွံသၟိၚ်မပြဲ၊ အဲဂှ် ဓဝ်လောကုတ္တဵုဒစိတ်ပြကာဂှ် ဂွံတၟတ်ဒၟံၚ်ပ္ဍဲဇကုတုဲ အဲဟွံဒိုက်ကၠၚ်ကၠောန်ရ မရှာတ်” ပစ္စေဂဗုတ်ဂး။ (ဇ—၅၂၉။ အစွောံ။) = “မင်းမြတ်၊ ငါသည် ကိုးပါးသောလောကုတ္တရာတရားကို နာမကာယဖြင့် သုံးသပ်သည်ဖြစ်၍ အထီးကျန်သောသူမဖြစ်။” (ညောင်ကန်) || ‘ထၟတ်’ ဟု လည်း အချို့ရေးသည်။')
,(5338,3,1,'ခြေသလုံး။ သလုံးသား။ (= ဂဒအ်ဗြာတ်)','“ပ္ဍဲဒေါဝ်ညး ဂမၠိုၚ်ဂှ် လၟသောနုတ္တရမွဲဂှ် ဇၞော်လောန်သၠုၚ်လောန် နူညးဂမၠိုၚ်ရ။ ဂတာဇိုၚ်ဍေံသတီုဇၞော် တမတ် တၞဴဍေံဇၞော် သော်ဍေံဒကာန် သော်ပါၚ်ဍေံဂၠိုၚ် ဖျုန်ဍေံကၟန်တုဲ ဍေံထတ်စောံပါလောန်ရ။” (ဇ— ၅၁၄။ အစွောံ။) = “ထိုမုဆိုးတို့၏အလယ်­ သောနုတ္တရမည်သောမုဆိုးသည် သူတကာတို့ထက် ပိုမြင့်ပိုကြီး၏။ ကြီးထူသောခြေဖဝါးရှိ၏၊ ခြေသလုံးကြီး၏၊ ဆံပင်ကြမ်း၏၊ တခဲနက်ထူသော ဖွားရရားထသော မုတ်ဆိတ်ကျင်စွယ်ရှိ၏။ အသားခိုင်ခံ့ကျစ်လစ်၍ အလွန်သန်မာ၏။”')
,(5339,3,1,'အတွေ့။ အထိအတွေ့။ ထိတွေ့မှု။','“ဗမၞးဂှ် ကလော်ဗြဴပတန်လဝ် လ္တူထဝဲါဍေံရ။ တမတ်ဒွံအရီုတြုံဂှ် ကလော်ဗြဴဂှ်ဂွံတုဲ ကိလေသတဏှာ ဇြဟာန်သၟိန်ပ္ဍဲဗမၞးဂှ် ကတဵုဒှ်တုဲ ဍေံဟွံဂွံစဗမၞးဂှ်ရ။” (ဇ—၄၃၂။ အစွောံ။) = “ပုဏ္ဏားကို ဘီလူးမသည် မိမိပေါင်ပေါ်­ထား၏။ ယောကျာ်းအထိအတွေ့အာရုံကို ရသည်ရှိသော် ဘီလူးမသည် ပုဏ္ဏား­ ကိလေသာတဏှာဖြင့် ချစ်ခြင်းဖြစ်ပေါ်၍ ပုဏ္ဏားအား မစားတော့ချေ။”')
,(5339,3,4,'ထိတွေ့သည်။ ထိတိုက်သည်။ ထိခတ်သည်။','“ကောန်ၚာ်တြုံဂှ် တၟတ်ဒွအ်ဒးဓဂဵုဆုတုဲ ဇိုၚ်ဂိအာရ။” = “ထိုကလေးသည် သစ် ၚုတ်ကိုထိခတ်မိ၍ ခြေထောက်နာသွားသည်။” || “ကောန်မဒြိုဟ်ကဵုမိမဂှ် မလေပ်တၟတ်ဒွအ်တဴဘဲ ဒဒိုက်ရ။” = “မိဘကို ပြစ်မှားသောသားသမီးသည် ဘေးဒုက္ခနှင့် တွေ့ကြုံရတတ်သည်။”')
,(5340,3,1,'လင်းတငှက်။',NULL)
,(5341,3,1,'မီးလောင်သောမီးစ။ မီးကျီး။ မီးစ။ (ပါဠိ— အၚ်္ဂါရ/ဥမ္မုက)','“လ္ၚပၟတ်” နှင့်အတူတူ')
,(5341,3,9,'(မီးစ) တစ်စ။','“(ကၞုဲသေနကဂှ်) ရပ်ကေတ်ပၟတ်ပမိတ်အှ်ော မွဲတမိတ်တုဲ အာကၠေံက္ဍိုပ်ကျာ စံၚ်စုတ်သ္ၚိမွဲရ။” (ဇ—၁၇၇။ အစွောံ။) = “သေနကမျောက်သည် လောင်နေသော ထင်းမီးစတစ်စကိုယူ၍ လေညာသို့သွား၍ တစ်ခုသောအိမ်ကို မီးရှို့လိုက်၏။” || “ဗောဓိသတ်ရပ်ကေတ် အှ်ောမွဲတမိတ်တုဲ ဗဟေက်ကၞုဲတုဲ ကၞုဲစလာ်အာကၠေံရ။” (ဇ—၂၅ဝ။ အစွောံ။) = “ဘုရားလောင်းသည် မီးစကိုကိုင်၍ ထိုမျောက်ကို ခြောက်လိုက်၍ ပြေးစေ၏။” (ညောင်ကန်) || “(ဣသိ)ရပ်ကေတ်ပၟတ်ကၟိတ်မွဲတုဲ (ကၠဟ်ဏာကၞုဲဂှ်ရ။)” (ဇ—၁၇၃။ အစွောံ။) = “ရသေ့သည် မီးစတစ်ခုကိုယူ၍ မျောက်အားပစ်လိုက်၏။”')
,(5342,3,1,'တမန်။','ကလုတ်တမာန် = သံတမန်။ (တမာန် = ကလုတ်)')
,(5343,3,1,'တာတမံ။','တၟိုန်လာ်အာ = တာတမံပြိုသွားသည်။')
,(5344,3,1,'ချက်ပြုတ်သူ။ အိုးသူကြီး။ ထမင်းချက်။ စားဖိုမှူး။ စားတော်ချက်။','“ဂြောဝ်တမောံပုၚ်ဂှ် ကၠာဟွံစိုပ်တ္ၚဲသဳဂှ် ရာန်သွက်လဝ်ဖျုန်လၟိုန်ရ။” (ဇ—၂၂ဝ။ အစွောံ။) (ဂြောဝ် = တမောံပုၚ်) = “စားဖိုမှူး(စားတော်ချက်)သည် ဥပုသ်နေ့မတိုင်မီ သားငါးတို့ကို ကြိုတင်ဝယ်၍ သိုမှီးနေကျဖြစ်၏။” || “တမောံပုၚ်ဂှ် ဍေံစှ်ေဍိုက်ဒၟံၚ်ဂၠုၚ်တုဲ ဍေံဒြာတ်ပုၚ်ဂှ် ကကၠုၚ်ကောံတုဲ—။” (ဇ—၂၃၃။ အစွောံ။) = “ထမင်းချက်သည် လှေဆင်းစီး၍ ထမင်းကိုကြဲသည် ရှိသော် ငါးတို့သည် စုရုံးရောက်လာကုန်၏။”')
,(5345,3,1,'လက်ဆောင်။',NULL)
,(5346,3,1,'လက်ဆောင်ပဏ္ဏာ။','“နတၟာဲဇၟိန်မဂၠိုၚ်ဂှ် ကွာဲလဗာဲအိုတ်ရ။” (ဇ—၅၃၁။ အစွောံ။) = “များစွာသောလက်ဆောင်ပဏ္ဏာဖြင့် ဆက်သကြကုန်၏။” || ‘တမာဲတ မိန်’ ဟုလည်း အနည်းအားဖြင့် တွေ့ရသည်။ || ‘စမာဲစမိန်’ နှင့်အတူတူ။')
,(5347,3,1,'လက်ဆောင်ပဏ္ဏာ။',NULL)
,(5348,3,4,'ပြည့်လျှံကျသည်။','“ဖရံက်ကဍုန်လဝ်ဂှ် ကၞမ်တုဲတၟိုဟ်ဒၟံၚ်ရ။” = “ချက်ထားသောငါးငပိသည် ဆူပြီးလျှံကျနေသည်။”')
,(5349,3,1,'စိတ်ချမ်းသာခြင်း။','“ယွံမၞးတံ၊ ညးဇမ္ဗုဒိပ်တေံဂှ် ပဗၞိက်ဇိက်ဗ္ၚ ကၠောန်ဒၟံၚ်ဟွံပိုတ် တုဲရောၚ်မဂွံစ ဟွံဂွံတမိုဟ်စိုတ် ညံၚ်အဲမွဲဝွံ(ရ။)” (ဍေံဒယှ်ေကြီုဒၟံၚ်ရ။) (၅၅ဝ။ ဇ—၄၆၆။ ၇— ၁၄၇။ အစွောံ။) = “ဇမ္ဗူဒီပါကျွန်း­ နေကုန်သောသူတို့သည် ကုန်သွယ်လယ်ထွန်လျက်မပြတ် အလုပ်လုပ်ပြီးမှသာ စားရကုန်၏။ ငါကဲ့သို့ ချမ်းသာကိုမရကုန်” ဟု သီချင်းသီ၍ ဥဒါန်းကျူး ၏။')
,(5350,3,1,'သိမ်းငှက်ရၚ်ဖြူ။',NULL)
,(5350,3,4,'ရည်ရွယ်သည်။ ရည်စူးသည်။','“ဝတ္ထုဒါန် ညးတၟအ်လဝ်ကဵုကျာ်တြဲဂှ် ညးတၞဟ်သ္အာၚ်ကေတ်ဟွံမာန်ရ။”= “မြတ်စွာဘုရားအား ရည်စူးထားသော လှူဖွယ်ပစ္စည်းကို သူတစ်ပါးတို့ မရယူနိုင်ပါ။”')
,(5351,3,1,'ကိုယ်လုံးကိုယ်ထည်။ အလုံးအထည်။ အလုံးအဖန်။','“ယွံတၠညး၊ ဇကုတ္ၜိုၚ် ထဝ်ဂှ် မတုပ်တဴညံၚ်ရဴတမှဳထဝ် မဂပ်ဂဝ်ထဏေန်စိုတ်ရောၚ်အဴ။” (ဇ—၄၈၂။ အစွောံ။) = “အရှင်မင်းကြီး၊ ထိုရွှေဆတ်၏ကိုယ်သည် ရွှေအလုံးအထည်နှင့်တူ၍ တပ်မက်မောဖွယ်ဖြစ်၏။” (မှတ်ချက်။ မြန်မာညောင်ကန်မူ­ ‘ရွှေပျဉ်ချပ်နှင့်တူ၏’ ဟုဆိုသည်။) || “ယွံသၟိၚ်သတ်ဇိုၚ်ပန်၊ တမှဳဇကုတၠအဲဂှ် ညံၚ်ရဴဥဿဘကီု—။” (ဇ—၂၉၅။ အစွောံ။) = “အိုအခြေလေးချောင်းသားတို့ ၏မင်း၊ သင်၏ကိုယ်လုံးကိုယ်ထည်သည် နွားလားဥဿဘ၏ ကိုယ်လုံးကိုယ်ထည်ကဲ့သို့ဖြစ်၏။” (မှတ်ချက်။ မြန်မာညောင်ကန်မူ­ ‘ပခုံး’ ဟုဆိုသည်။ ပါဠိဝေါဟာရမှာ ‘ခန္ဓ’ ဖြစ်သည်။ အၚ်္ဂလိပ်ဘာသာမူ ဟုဆိုသည်။)')
,(5352,3,1,'လောက်ကောင်။',NULL)
,(5353,3,1,'ယက်ကန်းယဉ်သွားနှတ်။',NULL)
,(5354,3,1,'သစ်စေး။ မျောက်နှဲစေး။','(= ဇၜိုတ်တယာၚ်) (ပါဠိ—ကၚ်္ကုဋ္ဌသိလေသ)')
,(5355,3,1,'ရဲတင်း။ ပေါက်ဆိန်။',NULL)
,(5356,3,16,'‘ကယျဝ်’ ရှု။',NULL)
,(5357,3,4,'၁။ ကိုင်းညွတ်သည်။','တယောဝ်စှ်ေ = အောက်သို့ကိုင်းကျသည်။ || “ပ္ဍဲကၞာၚ်ကြုက်မွဲ မတယောဝ်တလာဲစှ်ေရ။” (ဇ—၃ဝ၉။ အစွောံ။) = “အောက်သို့တွဲလျားကိုင်း ညွတ်ကျသော တစ်ခုသောသရက်ကိုင်း­—။”')
,(5357,3,4,'၂။ ဆန့်သည်။ ဆန့်ထုတ်သည်။','တယောဝ်ကအ် = လည်ဆန့်သည်။ || တယောဝ်ဏာတဲ = လက်ဆန့်ထုတ်သည်။ || “(ပံက်ဂှ် သၟိက်ဂွံစက ဂမၠိုၚ်တုဲ) ပ္ဍဲဇရေၚ်သြၚ်လစ တန်ဒၟံၚ်တုဲ ဍေံတယောဝ်ပ္တိတ်ကအ်ဍေံ—။” (ဇ—၂၃၆။ အစွောံ။) = “ထိုဗျိုင်းသည် ငါးတို့ကိုစားလို၍ အိုင်အနီး­နေ၍ လည်ကိုဆန့်ထုတ်၏။”')
,(5358,3,1,'လှည်းချိုင့်။ ရထားချိုင့်။',NULL)
,(5359,3,4,'အောက်သို့ညွတ်ကျသည်။ ညွတ်အိသည်။','“ကၞာၚ်ဆုတအ်ဂှ် ဍေံတယောဝ်လမောဝ်တဴ နကဵုသတ်ပ္ကဴတၞဟ်ဟ်သာ်ရ။” (ဇ—၅ဝ၄။ အစွောံ။) = “သစ်ကိုင်းတို့သည် အထူးထူးသော အသီးအပွင့်တို့ဖြင့် ညွတ်အိကုန်လျက်ရှိ၏။”')
,(5360,3,1,'‘တြ’ ရှု။',NULL)
,(5361,3,4,'ပါးအောင်လုပ်သည်။ နည်းပါးစေသည်။ လျော့ပါးစေသည်။','“ဂတှ်ေဆုဂှ်တီုအာ တှ်ေတရဳထောံညိ။” = “ထိုသစ်ပြားသည် ထူသွားသည်၊ အနည်းငယ် ခုတ်လွှာပစ်လိုက်ပါ။” || ဒ္ဂေတ်မတရဳကၠေံကိလေသ = ကိလေသာကို လျော့ပါးစေသောအကျင့်။ || ‘ကြဳ’ (ကြိ)၊ ‘တမြဳ’ (နဝိ) တို့လည်းရှု။')
,(5362,3,1,'ခရီး။','အာတရဴ၊ ကွာ်တရဴ၊ တိတ်တရဴ = ခရီးသွားသည်။ ခရီးထွက်သည်။')
,(5362,3,1,'(ဂဏန်း) ခြောက်။','တြဴစှ်ော = ခြောက်ဆယ်။')
,(5363,3,1,'သွားလာရန်ခက်ခဲသောခရီး။ ကန္တာရခရီး။',NULL)
,(5364,3,1,'ကျင်ကြီးစွန့်ခြင်း။ မစင်စွန့်ခြင်း။ အလေးသွားခြင်း။','အာတရဴဇၞော် = မစင်စွန့်သည်။ အလေးသွားသည်။')
,(5365,3,1,'ရေကြောင်းခရီး။',NULL)
,(5366,3,1,'ခြေကျင်ခရီး။ ကုန်းလမ်းခရီး။',NULL)
,(5367,3,1,'ကျင်ငယ်စွန့်ခြင်း။ ဆီးသွားခြင်း။ အပေါ့သွားခြင်း။','အာတရဴသၟတ် = အပေါ့သွားသည်။ ဆီးသွားသည်။')
,(5368,3,1,'ခရီးရှည်။','ကွာ်တရဴအဓါန် = ခရီးရှည်သွားသည်။')
,(5369,3,4,'၁။ ပြန့်သည်။ ပျံ့နှံ့သည်။ ဖြန့်သည်။','“နလၟေၚ်ဒလောံဗ္တောန်ဗောဓိသတ်ဂှ် တရးအာအလုံဇမ္မုဒိတ်တုဲ လုကဴဗၞတ်တွဵုထပှ်လ္ၚီသၞာံဂှ် စိုန်ဂွံတန်တဴရ။” (ဇ—၁၇၈။ အစွောံ။) = “ထို(ဘုရားလောင်း၏) အဆုံးအမသည် ဇမ္ဗူဒိပ်ကျွန်းအလုံးကိုပြန့်၍ (အနှစ်ခုနစ်ထောင်တို့) ပတ်လုံးတည်၏။” (ညောင်ကန်) || “လဗြဴမွဲဂှ် လ္ၚဴမသ္အးဂှ် တရးစဲလဝ်တုဲ ဂ္ဇံဒၟံၚ်တဴရ။” (ဇ—၂၅၂။ အစွောံ။) = “တယောက်သောမိန်းမအိုသည် နှမ်းတို့ကို အဖြူချွတ်၍ ဖြန့်(လှန်း)ပြီးလျှင် စောင့်လျက်နေ၏။” (ညောင်ကန်)')
,(5369,3,4,'၂။ ကျယ်စေသည်။ အကျယ်ချဲ့သည်။','“ဝတ္ထုဇာတ်ဝွံဂှ် ပ္ဍဲဂတတေံ ဟီုတွံတရးလဝ်တုဲရ။” = “ဤဇာတ်ဝတ္ထုကို ရှေ့တွင် အကျယ်ဟောထားပြီးပြီ။”')
,(5370,3,5,'အကျယ်အားဖြင့်။','“ယွံခမဳတံ၊ အဲဟီုဗွဲခမၞောန်တုဲ ဗွဲတရး သာရိပိုတ်ဂွံတိတ်ဟီု တွံကဵုညးဂှ် ဆလၟုဟ်ဝွံဟွံသေၚ်၊ နူမတုဲတေံရ” ကျာ်တြဲဂး။ (ဇ—၉၉။ အစွောံ။) = “ရဟန်းတို့၊ သာရိပုတ္တရာသည် ယခုအခါ­သာလျှင် ငါဘုရားသည် အကျဉ်းအားဖြင့် ဟောတော်မူအပ်သောစကားကို အကျယ်အားဖြင့် ဆိုသည်မဟုတ်သေး။ ရှေး­လည်း ဆိုဘူးသလျှင်ကတည်း။” (ညောင်ကန်)')
,(5371,3,4,'ဖြန့်ချဲသည်။ ပြန့်ကျဲအောင်လုပ်သည်။',NULL)
,(5372,3,4,'ဉာဏ်ကွန်ယက်ကို ဖြန့်ကျက်သည်။',NULL)
,(5373,3,4,'ဆန့်ထုတ်သည်။ ဖြန့်သည်။ ဖြာထွက်သည်။','“ပ္ဍဲကၞာၚ် ဆုမတရးတယောဝ် လတူဍာ်သြၚ်ဂှ် ဂစေံဂမၠိုၚ်ဒၟံၚ်။” (ဇ—၁၃၃။ အစွောံ။) = “များစွာကုန် သောငှက်တို့သည် သစ်ပင်၏ရေအထက်­ ဖြန့်သောအခက်တို့­ နေလျက်—။” (ညောင်ကန်)')
,(5374,3,4,'(ဣန္ဒြေမဆည်နိုင်ဘဲ) လှုပ်ရှားသည်။','“နူဝွံဒဵုတေံ ဗှ်ေတရးနရုတဴသွံ။” (ဇ—၃၃၈။ အစွောံ။) = “(သင်သည်) အကြင်ထိုမှဤမှ လှုပ်ရှား၏။” (ညောင်ကန်)')
,(5375,3,4,'သာသနာတော်ကို ပြန့်ပွားစေသည်။',NULL)
,(5376,3,1,'‘ကရေက်’ ရှု။',NULL)
,(5377,3,1,'ရေတလျှောက်။',NULL)
,(5377,3,4,'ရေတလျှောက်ဖြင့် ရေသွယ်သည်။','‘ကရံက်’ ရှု။')
,(5378,3,1,'ရေပြွန်ပေါက်။ ရေဆိုးပေါက်။ (ရေဆိုးများစီးသွား၍ ထွက်သွားရန်အပေါက်။)','“မၞိဟ်ဂမၠိုၚ်ရပ်လွဟ်တုဲ ညးဗက်အာတုဲ ကလော်ဗြဴဂှ် ဍေံဂၠုက်တိတ်အာ ပ္ဍဲတရံက်ဍာ် ကၟာၚ်ဍုၚ်ဂှ်ရ။” (ဇ—၅၁၃။ အစွောံ။) = “လက်နက်စွဲကုန်သောသူတို့သည် ဘီလူးမကို လိုက်ကုန်၏။ ဘီလူးမသည်ပြေး၍ မြို့ရိုးရှိရေပြွန်ပေါက်မှ လျှိုထွက်သွား၏။”')
,(5379,3,1,'တံခါး။','ပါၚ်တရၚ် = တံခါးပေါက်။ || တရၚ်ဝစ္စမက် = စအိုပေါက်။')
,(5380,3,1,'တံခါးမုခ်။ ဝင်းတံခါး။ ဂိတ်ဝတံခါး။ (ပါဠိ—ကောဋ္ဌက) (ဂအတေ)','တရၚ်ကတ်ဘာ ဇေတဝန် = ဇေတဝန်ကျောင်းတံခါးမုခ်။ || “(ထေရ်ဂှ်) ဒၟံၚ်တဴပ္ဍဲပါၚ်တ ရၚ်ကတ်ဘာဇေတဝန်ဂှ်ရ။” (ဇ—၂ဝ၂။ အစွောံ) = “ထိုမထေရ်သည် ဇေတဝန်ကျောင်း၏တံခါး မုခ်­ နေ၏။’ || “(ပြဘာတ်ဂှ်) ဍေံတွဳဗွိုၚ်ကေတ် မှာဇန်တံဗွဲမဂၠိုၚ်တုဲ ဍေံတိတ်စိုပ်တရၚ်ကတ် ဘာဇေတဝန်ရ။” (ဇ—၂၂၉။ အစွောံ။) = “(ထိုပရိဗိုဇ်သည်) လူများဖြင့်ခြံရံလျက် ဇေတဝန် ကျောင်းတော်သို့ သွားလတ်သည်ရှိသော် — ဇေတဝန်ကျောင်းတော်တံခါးမုခ်ကိုမြင်၍—။” (ညောင်ကန်) || “ပြတရၚ်ကတ်ပြာသာဒ်ဍုၚ်တက္ကသဵု။” = “တက္ကသိုလ်ပြည်နန်းပြာသာဒ်၏ တံ ခါးမုခ်ဦးမျှော်စင်။” ‘ကတ်’ (န) လည်းရှု။ (မှတ်ချက်။ ‘ကတ်’ နှင့် ‘တရၚ်ကတ်’ အဓိပ္ပါယ် ဆက်စပ်မှုမရှိသည်ကို သတိပြုရာသည်။)')
,(5381,3,1,'ရေပြွန်ပေါက်တံခါး။ (ရှေးသုံး)',NULL)
,(5382,3,4,'၁။ စီတန်းထားသည်။ အစဉ်သဖြင့်ထားသည်။','“(ဗောဓိသတ် သီုကွဳစောတ်မသုန်ကၠံ အာစိုပ်ကန္တာဒမံၚ်ကလော်တံဂှ်တုဲ) တလိုဟ်ကွဳ ဗ္ဂေတ်တရေၚ်လဝ် ဗိုၚ်လဝ်မၞိဟ်ကီုဂၠဴကီု—။” (ဇ—၁။ အစွောံ။) = “ဘုရားလောင်းသည် လှည်းငါးရာနှင့်တကွ ဘီလူးတို့နေရာ ကန္တာရသို့ ရောက်သည်ရှိသော် လှည်းတို့ကိုချွတ်ကုန်၍ လှည့်၍စီတန်းထားပြီးလျှင် လူနှင့်နွားတို့ကို ဝိုင်းထားစေ၏။” || “(ဗောဓိသတ်ဒှ်စိၚ်ဗ္တာၚ်) ဂဍောၚ်မတ်ၜါ ညံၚ်ကလောံမၞိက် မစွံပြေၚ်တရေၚ်လဝ် ကီု။” (ဇ—၇၂။ အစွောံ။) = “ဘုရားလောင်းသည် ဆင်ဖြူဖြစ်၍ မျက်လုံးနှစ်လုံးတို့သည် စီ တန်းထားရှိသော ပတ္တမြားတုံးကဲ့သို့ဖြစ်၏။” || “အဲစလာ်ဗၞုဟ်မသုန်ညိ” (အ္စာဂှ်)ဂးတုဲ တရေၚ် လဝ်ဗၞုဟ်မသုန်ရ။ (ဇ—၁၁၆။ အစွောံ။) = “ငါးစင်းသောလှံတို့ကို ခုန်အံ့” ဟု(ထိုဆရာ)ကြံ၍ (လှံငါးစင်းတို့ကို) အစဉ်သဖြင့်ထား၏။ (ညောင်ကန်)')
,(5382,3,4,'၂။ ကြီးရင့်စေသည်။ ကြီးထွားစေသည်။','“အပ္ပမာဒဂုန် မှတ်ညံၚ်မဂွံ လ္ပတရေၚ်ဟိုတ်မာဲညိ။” (ဇ—၇၁။ အစွောံ။) = “မမေ့မလျော့ ခြင်းဂုဏ်ကျေးဇူးကို ရအောင်မဖြစ်မနေအားထုတ်၍ မေ့လျော့ခြင်းကို မကြီးထွားပါစေနှင့်။”')
,(5383,3,4,'၁။ ရင့်စေသည်။ ရင့်မာစေသည်။ ကြီးရင့်စေသည်။','“(ပဋိပတ်မပြဲဂမၠိုၚ်ဂှ်) ပတၠတုဲ ဇၟာပ်သရၚ်သီုဖအိုတ် လ္ပတရံၚ်ဟိုတ်မာဲညိ။” (ဇ—၄၉။ အစွောံ။) = “မြတ်သောအကျင့်တို့ကို ပိုၚ်ဆိုင်ကျင့်သုံး၍ အမှုကိစ္စဟူသမျှ­ မေ့လျော့ခြင်းကို မကြီးရင့်ပါစေနှင့်။”')
,(5383,3,4,'၂။ တင်းကျပ်စေသည်။ တင်းမာစေသည်။','“နသၞာ်ၚာၚ်အဲ သကေပ်ကြေဝ်ကၠေံကအ်ဗှ်ေရ” မာတ်ဂးသာ်ဝွံတုဲ ဂတာံသကေပ်တရံၚ်ၚာၚ် (ပ္ဍဲကအ်ပံက်ဂှ်)ရ။ (ဇ—၃၈။ အစွောံ။) (တရံၚ်ၚာၚ် = ပတေၚ်ၚာၚ်) = “ငါ့လက်မဖြင့် နင့်လည်ကို ညှပ်ဖြတ်ပစ်အံ့” ဤသို့ဆိုရင်း ပုဇွန်သည် လက်မကိုတင်းမာစေ၍ ဗျိုင်း၏လည်ကို ပိုတိုး၍ညှစ်၏။')
,(5384,3,4,'အားတင်းထားသည်။ စိတ်ကိုခိုင်အောင်ထားသည်။','“ကာလဆဵုဒဒိုက်လေဝ် လ္ပဖဍိုန်စိုတ်၊ တရံၚ်လဝ်စိုတ်ညိ။” = “ဒုက္ခတွေ့သောအခါ­လည်း စိတ်ဓါတ်မကျစေနှင့်၊ အား တင်းထားပါ။”')
,(5385,3,4,'ဉာဏ်ကိုရင့်ကျက်စေသည်။','“ပ္ဍဲကုသဵုလေဝ် ကဵုဗိုန်ဂၞပ် ပခိုၚ်စိုတ် ဇၞော်လွဳ တရံၚ်ညာဏ်ညိ။” (ဇ—၄ဝ။ အစွောံ။) = “ကုသိုလ်တရား­လည်း စွဲမြဲစွာအလိုရှိသည်ဖြစ်၍ စိတ်ကိုခိုင်မြဲစေ၍ လုံ့လပြု၍ ဉာဏ်ကိုရင့်ကျက်အောင် မွေးမြူလော့။”')
,(5386,3,4,'ရင့်မှည့်စေသည်။ ရင့်မာအောင်ပြုသည်။ ရင့်ကျက်အောင်ပြုသည်။','“အဲဂွံပ္တုဲဒါန် ဒ္ဂိုန်သဳ ပၟဝ်ဘာဝနာ တရံၚ်တဍုဟ်အာ ပါရမဳစှ်ဂှ်တုဲ အဲဟွံ ဒးစံၚ်တူရ။” (ဇ—၂၄၃။ အစွောံ။) = “ငါသည် အလှူဒါနပြုခြင်း၊ သီလစောင့်ခြင်း၊ ဘာဝနာပွားခြင်းဖြင့် ပါရမီဆယ်ပါးကို ရင့်မာအောင်ပြုသဖြင့် ပူပန်ရန်မလိုတော့ပြီ။” || “ယွံဗမၞး၊ ဍေံမတရံၚ် ထဍုဟ်ကဵုဒတုဲမြမောဝ်ပိုဲ ဓဝ်ဟိုတ်ကဵုဓဝ်ဖဵုဂှ်ကီု သ္ဂောံတီတုဲ သ္ဂောံဒ္ဂေတ်ဗက်တုဲ ဗွဲသွာဂွံအာစိုပ် နိဗ္ဗာန်ဂှ် — ဂှ်ဓဝ်ဟိုတ်ကဵုဓဝ်ဖဵုဂှ် အစာဟီုပ္တီကဵုအဲညိ” သၟိၚ်ဂး။ (ဇ—၅၁၅။ အစွောံ။) = “ဆရာ ပုဏ္ဏား၊ ငါတို့၏အကျိုးစီးပွားကို ရင့်မှည့်ခြင်းသို့ ရောက်အောင်ပြုပေးသော အကြင်အကြောင်း တရားနှင့်အကျိုးတရားကို သိ၍ကျင့်သုံးရလျှင် နိဗ္ဗာန်သို့အလွယ်ရောက်နိုင်သော ထိုအကြောင်း တရားနှင့်အကျိုးတရားကို ဆရာသည် အကျွန်ုပ်အားသိအောင်ပြောကြားပါလော့။” || “(မၚ်ဗၠာဲဂှ်) ဟိုတ်နူဟွံမွဲပ္တုဲလဝ်ဒါန်သဳလဘာဝနာ ဟိုတ်နူဟွံဂွံရာဒနာ တရံၚ်လဍုဟ်လဝ်ပါရမဳတုဲ မဍိုန်ဂ တိဂဒိုက်ညာန်—။” (ဇ—၁၂၃။ အစွောံ။) = “ထိုလုလင်သည် ဒါနသီလဘာဝနာ မပြုထားရသဖြင့်၊ ပါရမီရင့်အောင် ဆုမတောင်းမဖြည့်ကျင့်ထားရသဖြင့် ဉာဏ်ပညာနုန့်နှေးရ၏။”')
,(5386,3,1,'ရင့်မှည့်ခြင်း။ ရင့်မာခြင်း။ ရင့်ကျက်ခြင်း။ ရင့်မှည့်၍ပေးသောအကျိုး။','“ယွံသၟာဂလုံ၊ ပ္ဍဲဘဝအ တိက်တေံဂှ် အဲဒှ်ဒိုက်ဂတ် လိၚ်စကဵုသေဋ္ဌဳဂှ် ဂွံမၚ်သဳမွဲဒကုတ်တ္ၚဲကီု စုတိတုဲ ဒဒှ်သၟိၚ်ပိုန်ဟာန်ကျာ် သြဳဇၞော်ဟေၚ် အဲမကလိဂွံ၊ တရံၚ်ထဍုဟ်ကုသဵုဝွံဂှ် ဇၞော်လောန်သန်ဟေၚ်ရ။” (ဇ—၅၁၅။ အစွောံ။) = “အို—ဆတ္တာသည်၊ အတိတ်ဘဝက ငါသည် သူဆင်းရဲဖြစ်၍ သူဌေးအထံ­ သူရင်း ငှားလုပ်၍ နေ့တစ်ဝက်မျှသာ သီလစောင့်ရ၏။ စုတေ၍ မင်းအဖြစ်နှင့် ကြီးစွာသောစည်းစိမ် ကျက်သရေကို ငါရ၏။ ဤကောင်းမှု၏ ရင့်မှည့်၍ပေးသောအကျိုးအမြတ်ကား အလွန်ကြီးကျယ် စွတကား။” || “ယွံမၞးတံ၊ ပ္ဍဲလိုက်ဝွံ ပွသတ္တအ်မလ္ၚတ်လဝ်ထေက် ကုသဵုကံကီု အကုသဵုကံကီု မ လ္ၚတ်လဝ်ဂှ် မလ္ၚုအာနူတြံၚ်လဍုဟ်ဖဵုမ္ဂးဂှ် ဟွံမွဲရ။” (ဇ—၄၉၈။ အစွောံ။) = “အချင်းတို့၊ ဤလောက­ သတ္တဝါတို့လေ့ကျက်ထားသော ကုသိုလ်ကံသည်၄င်း အကုသိုလ်ကံသည်၄င်း အချည်း စည်းအကျိုးမဲ့ဟူ၍မရှိ၊ ရင့်မှည့်၍အကျိုးပေးသည်သာတည်း။” || “ရသိမသက္ကုဒုဟ်ဂှ် သၟိၚ်ဂှ် သကုတ်ကၠေံအဝဲရ။ ကုသၟိၚ်မပြိုက်ညး ပွမသကာတ်မြဟ်မဖှ်သာ်ဂှ် တရံၚ်လဍုဟ်ဖဵုမရိၚ်ကတၚ် လောန်ဂှ် က္တဵုဒှ်တုဲရ။ ဟိုတ်ပွဂှ်ရ ဒးစှ်ေတန်ဒၟံၚ် ပ္ဍဲနရက်အဝိက်တေံရ။” (ဇ—၃၁၃။ အစွောံ။) = “အပြစ်မဲ့သောရှင်ရသေ့အား ထိုမင်းသည် ခြေလက်အၚ်္ဂါတို့ကို ဖြတ်ပစ်၏။ ထိုကဲ့သို့သောကြမ်း ကြုတ်မှုဖြင့် ညှဉ်းဆဲတတ်သောထိုမင်းအား အလွန်ပူလောင်ခါးသီးသော အကျိုးပေးခြင်းသည်ဖြစ်၏။ ထိုမကောင်းမှုကြောင့် အဝီစိငရဲ­ ကျရောက်၏။” || “ခမဳမသုန််ကၠံဂှ်တုန်လေဝ် အာစိုပ်တရံၚ်လဍုဟ်ညာဏ်တုဲရ။” (ဇ—၁၁။ အစွောံ။) = “ထိုအခါ ရဟန်း (ငါးရာ) တို့အား ဉာဏ်ရင့် ခြင်းသို့ရောက်၏။” (ညောင်ကန်)')
,(5387,3,3,'ကြည့်ကောင်းသော။ သပ်ရပ်သော။','“နွံသၟတ်ဗြဴမွဲဂှ် ဇကုဍေံကြောအ်ဒၟံၚ်၊ ဆတၠုၚ်လအာဍေံဂှ် တရံၚ်တရာတဴ။” (ဇ—၁ဝ၈။ အစွောံ။) = “တစ်ယောက်သောမိန်းမငယ်သည် ဆူသောကိုယ်ရှိ၏။ အသွင်အပြင်သာလျှင် သပ်ယပ်ကြည့်ကောင်း၏။”')
,(5389,3,3,'ကြည့်ကောင်းသော။ သပ်ရပ်သော။','“ယွံသၟိၚ်(မပြဲ)၊ ဍေံမၞုံပက္ကတိမၞုံရေက်သော် မုဟ်ပါၚ် ညးမတရံၚ်တရဴဒၟံၚ်တံဂှ် တြုံမဍိုက်ပေၚ်တဴကေုာံအာစာရဝတ် မၞုံအယောၚ်အလာမဆာဲ —။” (ဇ—၁၈၄။ အစွောံ။) = “မင်းမြတ်၊ ထိုကောင်းသောအကျင့်နှင့်ပြည့်စုံသော၊ မင်းအား လျော်စွာဖြစ်သော၊ ကောင်းသောအခြင်းအရာအားဖြင့် ပြုပြင်တတ်သောဆံမုတ်ဆိတ်ရှိသော ယောကျာ်းသည်—။” (ညောင်ကန်) (မှတ်ချက်။ ‘တရံၚ်တရာ’ နှင့် ‘တရံၚ်တရဴ’ ဤဝေါဟာရ နှစ်ခုတို့သည် စာလုံးပေါင်းပုံမှာလည်း အနည်းငယ်မျှသာကွဲလွဲ၍ အဓိပ္ပါယ်မှာလည်း တူနေသဖြင့် တစ်ခုတည်းသောဝေါဟာရပင် ဖြစ်နိုင်သည်ဟု ယူဆပါသည်။ အဘယ်စာလုံးပေါင်းပုံက အမှန် ဖြစ်သည်ကို မဆုံးဖြတ်နိုင်သေးပါ။)')
,(5390,3,11,'(န) တုရိုဏ်တိုင်။ မုခ်ခုံးတိုင်။ တံခါးအုံ။ (ပါဠိ—တောရဏ)',NULL)
,(5391,3,1,'မြို့ပြင်ပ။ ဆင်ခြေဖုံး။ (စုဗုရဗစ)','“ဍုၚ်ဗာရာဏသဳဝွံ ဇၞော်စှ်ၜါယောဇနာနာၚ်၊ တရပ် ပ္ဍဲမ္ၚးဂှ် ပိကၠံယောဇနာရောၚ်။” (ဇ—၅။ အစွောံ။) = “ဗာရာဏသီပြည်ကြီးသည် မြို့တွင်းတစ် ဆယ့်နှစ်ယူဇနာရှိပြီး မြို့ပယူဇနာသုံးရာရှိ၏။”')
,(5392,3,1,'‘ကရာပ်’ (န) ရှု။',NULL)
,(5393,3,4,'(မိုး) သည်းထန်စွာရွာသည်။','“အခိၚ်ဗြဲတရိုပ် လ္ပကွာ်ဂၠံၚ်ညိ။” = “မိုးသည်းထန်စွာ ရွာသောအခါ လမ်းမလျှောက်ပါနှင့်။” || ‘ကြိုပ်’ ဟုလည်းရေးသည်။')
,(5393,3,1,'အလို။ စိတ်အလို။','‘သ္ဂောံသ္ဍိုက်ပေၚ်ကဵုတရိုပ်အဲရောၚ်။’ (ဇ—၂၆၆။ အစွောံ။) = ‘ငါ၏အလိုသည် ပြည့်လတ္တံ့။’')
,(5394,3,4,'(လက်ဆောင်၊ ဆုလာဘ်စသည်) ချီးမြှင့်ပေးအပ်သည်။','“ကွာန်မွဲဂှ် မွဲသၞာံကၠေဝ် ထဝ်မွဲလက်ဂှ်မွဲ၊ ဗြဴဝုတ်ကမၠောန်ဂှ်လေဝ်ၜါ၊ သ္ၚိဂတဵုဇၞော်ဂှ်လေဝ်မွဲ၊ ကွဳရတ်မပ္ကီုကဵုချေံဂှ်လေဝ်မွဲ၊ ဂၠိက်ယာတ်ထဝ်သြန်ဗွဲမဂၠိုၚ်ဂှ် သၟိၚ်တရိုပ်ကဵုလၟရ။” (ဇ—၅၃၃။ အစွောံ။) = “တစ်နှစ်လျှင် ရွှေတစ်သိန်းအခွန်ထွက်သော ရွာတစ်ရွာကို၄င်း၊ အလုပ်အကျွေးမိန်းမပျိုနှစ်ယောက်ကို၄င်း၊ ပျဉ်ထောင်အိမ်ကြီးတစ်လုံးကို၄င်း၊ မြင်းကသောရတနာရထားတစ်စီးကို၄င်း၊ အဝတ်အစားရွှေငွေများ စွာကို၄င်း၊ မင်းသည် မုဆိုးအား ချီးမြှင့်ပေးအပ်၏။”')
,(5395,3,4,'ရောင့်ရဲသည်။—စေသည်။','“ခမဳမလုလန်ဂှ် မပ္တံဖျုန်ကေုာံပုၚ်သြောံဂန္ဓသာလဳ မၞုံကဵုရှ်တၞဟ်ဟ်သာ်ဂှ် ပပြဘိုက်တုဲ ဘောဇိုန်သာ်ဂှ် ဟွံတရိုပ်ကဵုစိုတ်ရ။” (ဇ—၄၃၄။ အစွောံ။) = “တစ်ယောက်သော လော်လည်သောရဟန်းသည် အထူးထူးသောအရသာရှိသော သလေးဆွမ်း အမဲဟင်းလျာ အစရှိသည်တို့ကို စား၍လည်း ထိုအာဟာရဖြင့် မရောင့်ရဲ။” (ညောင်ကန်) || “မူရဴညးမွဲ တရိုပ်ကဵုစိုတ်ဍေံမာန်ရော။” = “အဘယ်သူသည် သူ့စိတ်အလိုကို ရောင့်ရဲစေနိုင်မည်နည်း။”')
,(5396,3,4,'ဝမ်းမြောက်ဝမ်းသာ သဒ္ဓါတရားဖြင့် အလှူပေးသည်။','“သၟိၚ်ကီု ဗောဓိသတ်ကီု ညာတ်ပစ္စေဂဗုတ်တုဲ မိပ်စိုတ်သ္ဇုၚ်သ္ဍိုက်တုဲ — မပ္တံကွာၚ်စၞဂှ် တရိုပ်ကဵုကၠာတုဲ ဘောဇိုန်မပြဲ ပြဲတံဂှ် တရိုပ်ကဵုဒါန်ပၠန်ရ။” (ဇ—၄၉၅။ အစွောံ။) = “မင်းသည်၄င်း ဘုရားလောင်းသည်၄င်း အရှင်ပစ္စေကဗုဒ္ဓာတို့ကိုမြင်၍ ဝမ်းမြောက်ကြည်ညို၍ မုန့်ပဲအစရှိသည်တို့ကို ဦးစွာပေးလှူ၍ မြတ်သောဘောဇဉ်တို့ကို ပေးလှူပြန်၏။”')
,(5397,3,1,'အလို။ စိတ်အလို။','“ပၟတ်ဂြိုပ်တံဂှ် အောဟ်ကၠံကွဳလ္ၚီကွဳ ဗဝ်စံၚ်စုတ်ကဵုဍေံကီုလေဝ် တရိုပ်စိုတ်ပၟတ်ဂှ် မဟဲအာကီုဟာ။ ဗဝ်စုတ်အောဟ်ဂၠိုၚ်က္ဍၚ် ပၟတ်ဂှ် ဂဵုဂၠိုၚ်တိုန်က္ဍၚ်အာပၠန်ရအဴ။” (ဇ—၄၆၇။ အစွောံ။) = “တောမီးတို့သည် ထင်းလှည်းတစ်ရာတစ်ထောင်ကို စုထည့်၍ရှို့သော် လည်း မီး၏အလိုသည်မပြေ။ ထင်းများစွာပုံထည့်လေလေ မီးသည် ပို၍လောၚ်မြိုက်လေလေဖြစ် ၏။” || “ချေံဗြဴဂှ် ဟွံကလိဂွံညံၚ်တရိုပ်စိုတ်တုဲ သေၚာမ်စံၚ်တူတုဲ—။” (ဇ—၂၆၆။ အစွောံ။) = “ထိုမြင်းမသည် စိတ်အလိုအတိုင်း မရသည်ရှိသော် နှလုံးမသာမယာဖြစ်၏။” ||  အာစိုပ်တရိုပ်စိုတ် = စိတ်အလိုပြည့်သည်။ ရောင့်ရဲကျေနပ်သည်။ || ‘ပေၚ်တရိုပ်စိုတ်’ (ကြိ) လည်းရှု။')
,(5398,3,4,'ဝမ်းမြောက်စွာကျွေးမွေးသည်။','“နပုၚ်သွအမာဲကဖျုန်တံဂှ် တရိုပ်ဗစတဴကၟုဲဂမၠိုၚ် ရ။” = “ထမင်းအမဲသားငါးဟင်းလျာတို့ဖြင့် ဧည့်သည်များကို ကျွေးမွေးသည်။”')
,(5399,3,4,'ဟောင်းသည်။','“ကွဳလိုန်အဲဂှ် တြေံအာရ။” = “ကျွန်တော့်စက် ဘီးသည် ဟောင်းသွားပြီ။”')
,(5399,3,3,'ဟောင်းသော။','မၞိဟ်တြေံ = လူဟောင်း။')
,(5400,3,1,'ဘာသာပြန်။ နိဿယ။',NULL)
,(5401,3,4,'(အမှုန့်စသည်ကို ဖြူးချသောအခါ) လွင့်ဝဲပျံကျသည်။','“(ကလော်ဂှ်) ကနှိက်ကြ ကောတ်မဇိပ်ဂၠိပ် ဍေံဖရုဲဖျေံရ။ ကနှိက်ကြကောတ်တရုဲစှ်ေတုဲ လုပ်အာမုဟ်ၝဗောဓိသတ်ရ။”(ဇ— ၁၅၅။ အစွောံ။) = “ထိုဘီလူးသည် သိမ်မွေ့သောအမှုန့်ကို ဖြူးချ၏။ အမှုန့်သည် လွင့်ဝဲပျံကျ ၍ ဘုရားလောင်းအဖ၏ နှာခေါင်းပေါက်သို့ဝင်၏။”')
,(5402,3,4,'လောင်းချသည်။ လွှချသည်။','တရိုဟ်ဍာ် = (အလှူ) ရေစက်ချသည်။|| တရိုဟ်ဇ နိက် = ကန့်လန့်ကာချသည်။ || ‘စရိုဟ်’ ရှု။')
,(5403,3,1,'‘တၠ’ ရှု။',NULL)
,(5404,3,1,'၁။ သေတ္တာ။ တံတင်း။','‘ကလာ’ ဟုလည်းရေးသည်။')
,(5404,3,1,'၂။ လူသေထည့်သည့်ခေါင်း။',NULL)
,(5404,3,1,'၃။ ဖိန်းနွှဲခါ။',NULL)
,(5405,3,1,'သန်ဘက်ခါ။ မနက်ဖြန်ပြီး နောက်တစ်နေ့။','“သ္အာယးရ၊ သ္အာတလဳရ” ဆမ ချပ်ဒၟံၚ်သာ်ဂှ် ဒဵုပိဂိတု—။ (ဇ—၁၁၄။ အစွောံ။) = “မနက်ဖြန်သွားအံ့၊ သန်ဘက်ခါသွားအံ့” ဟု ကြံလျက်နေသည်မှာ သုံးလတို့လွန်ကုန်၏။')
,(5406,3,4,'တွဲချည်ပြီး ရေထဲတွင်ချထားသည်။','“ကဂှ်ဒက်တုဲ တလဲလဝ်ပ္ဍဲဍာ်ညိ။” = “ငါးကို ချည်ပြီး ရေထဲတွင်ချထားပါ။” || “တဲဍေံရပ်လဝ်ဂၠုၚ်တုဲ ဍေံတလဲလဝ်ဇကုဍေံပ္ဍဲဍာ်ရ။”= “သူ၏လက်ဖြင့် လှေကိုကိုင်ထားပြီး သူ၏ကိုယ်ကို ရေထဲတွင်တွဲချထားသည်။”')
,(5407,3,1,'၁။ နှင်တံ။',NULL)
,(5407,3,1,'၂။ စင်ကြယ်ခြင်း။ တင့်တယ်ခြင်း။','‘စလး’ ရှု။')
,(5407,3,4,'ရှင်းသည်။ ရှင်းလင်းသည်။',NULL)
,(5408,3,1,'တင့်တယ်စမ္ပယ်ခြင်း။ အဆင်းအလှ။ အသရေ။','တလးစရာဲရုပ်/စလးစရာဲရုပ် = တင့်တယ်သောရုပ်အဆင်း။ || “သၟတ်ဗြဴမွဲ သကိုပ်သာကမၠတ် ညာတ်တလးစရာဲ ရုပ်စိုတ်စပ်အာ ဂိုၚ်လဝ်ပသမ္ဘာရ။” (ဇ—၆၃။ အစွောံ။) = “ခိုးသားခေါင်းဆောင်သည် ထိုမိန်းမငယ်၏ ရုပ်အဆင်းအလှကိုမြင်လျှင် တပ်စွန်း၍ မယားအဖြစ်သိမ်းယူလိုက်၏။” || “ဂၞကျာ် ညာတ်ရုပ်သာ်စလးစရာဲဥပ္ပရာဇာဂှ်တုဲ စိုတ်စပ်အာ။” (ဇ—၄၇၂။ အစွောံ။) = “မိဖုယားသည် အိမ်ရှေ့မင်းသား၏ တင့်တယ်သောရုပ်အဆင်းကိုမြင်၍ စိတ်တပ်စွန်းသွား၏။” || “ရုပ်သာ်ကျာ် သြဳတလးစရာဲကျာ်ဂမျိုၚ် မၞုံအရံၚ်အံၚ်သူလျး မကလိကၠေံရုပ်မၞိဟ်ဒေဝတဴဂမၠိုၚ်။” (ဇ—၅၁၄။ အစွောံ။) = “လူနတ်တို့၏ ရုပ်အဆင်းထက်သာလွန်သော အရောင်အဆင်းတော်ဖြင့်ပြည့်စုံသော ဘုရားရှင်၏ တင့်တယ်စမ္ပယ်သော ရုပ်အဆင်းအသရေတော်။” || “နဣဓိသၟိၚ်ဣန်ဂှ် တၞံဝိဂှ် မ ဍိုက်ပေၚ်တဴကေုာံကၞာၚ်ဇၞော်သၟတ် သတ်မၞုံကုရှ် မဍိုက်ပေၚ်ကေုာံတလးရာဲ က္တဵုဒှ်ရ။” (ဇ—၄၂၉။ အစွောံ။) = “သိကြားမင်း၏တန်ခိုးဖြင့် ထိုရေသဖန်းပင်သည် အကိုင်းအခက်တို့နှင့်ပြည့်စုံ၍ အ ရသာရှိသောအသီးတို့ဖြင့် တင့်တယ်ခြင်းနှင့်ပြည့်စုံစွာ ဖြစ်ပေါ်လာ၏။” || “သၟတ်ဍိက်ဂှ် — ဒှ်ဗၠာဲ နွံကဵုတလးစရာဲရုပ်သာ်သန်။” (ဇ—၁၂၅။ အစွောံ။) = “ထိုကျွန်မသားသည် အရွယ်ရောက်၍ အလွန်တင့်တယ်သော ရုပ်အဆင်းရှိ၏။” || “(ဗောဓိသတ်) အာက္တဵုဒှ်ၜိုပ်ထဝ် က္တဵုဒှ်ဇၞော်အာဒှ်ဗၠာဲ အတ္တဘဴဇကုဇၞော် အာစိုပ်ကၞတ်တလးစရာဲ—။” (ဇ—၁၃၆။ အစွောံ။) = “ဘုရားလောင်းသည် ရွှေဟၚ်္သာအမျိုး­ဖြစ်၍ အရွယ်သို့ရောက်သည်ရှိသော် ကြီးသောခန္ဓာကိုယ်ရှိ၍ အထွတ်အထိပ်သော တင့်တယ်ခြင်းအစုသို့ရောက်၏။”')
,(5409,3,5,'ခဏခဏ။ အမြဲတမ်း။','“နနဲသာ်ဝွံ မဂၠိုၚ်ကဵုဝါ ၜိုန်သၟိၚ်ဟီုတဴကီုလေဝ် ဂၞကျာ်ဟွံဒိုအ် အာတ်တဴဒၟံၚ်လွဵု တလံက်တလံက်တုဲ (သၟိၚ်ဒးကဵုလွဵုရ။)” (ဇ—၆။ အစွောံ။) = “ဤနည်းအားဖြင့် ကြိမ်ဖန်များစွာ မင်းသည် ပြောဆိုတားမြစ်သော်လည်း မိဖုရားသည် ထိုဆုကိုသာလျှင် ခဏခဏတောင်းနေရာ မင်းသည် ထိုဆုကိုပေးလိုက်ရ၏။”')
,(5410,3,1,'အမြှောင့်။ မျက်နှာ။ ထောင့်။ ဘက်။','ပန်တလၚ် = လေးမြှောင့်။ လေးဘက်။ || “ကၟာမွဲဂှ် ဇမၠိၚ်အနာံပန်ကၠၚ်ဓဝ် မွဲမွဲတလၚ် မၞုံဗၞတ်မွဲယောဇနာရ။” (အဓါန်မသုန်။ အစွောံ။) = “ရေကန်တစ်ခုသည် အလျားအနာံလေးဘက်ညီဖြစ်၍ ဘက်တစ်ဘက်လျှင် တစ်ယူဇနာအရှည် ရှိ၏။” || “ခေသရာဇာဒိသိုၚ်ဝွံ ကၠဵုဂှ် ၜိုန်ယုတ်နူဇကု ဇၟာပ်တလၚ်ကီု ဇိုန်ဇကုပဍိက်ခစတုဲ (ဖျုန်သတ်အလုံဂြိုပ် ဗစကၠဵုဂှ်ရ။)” (ဇ—၁၄၃။ အစွောံ။) = “ကေသရာခြင်္သေ့မင်းသည် မြေခွေးက (မည်သည့်ရှုထောင့်ကမဆို) အဘက်ဘက်တွင် မိမိထက်ယုတ်နိမ့်သော်လည်း မိမိထံကျွန်ခံခစားသည်ရှိသော် တောအလုံးမှသားမျိုးစုံကို မြေခွေးအားကျွေး၏။”')
,(5411,3,1,'စိုင်။','(ပါဠိ—ရောဟိတမိဂ)')
,(5412,3,4,'အမှတ်မှားသည်။ ထင်မှတ်မှားသည်။ မမှတ်မိဖြစ်သည်။','“ကောန်ဗှ်ေဂှ် အဲဟွံဂွံဆဵုဍေံလအ်တုဲ ဍေံဇၞော်တိုန် အဲတလိၚ်အာဍေံရ။” = “နင့်ကလေးကြီးလာတယ်၊ သူ့ကို ငါမတွေ့ရတာကြာလို့ သူ့ကို ငါမမှတ်မိတော့ပါ။” || တလိၚ်ဂၠံၚ်၊ တလိၚ်တရဴ = လမ်းမမှတ်မိ ဖြစ်သည်။ မျက်စိလည်လမ်းမှားသည်။ || တလိၚ်ဒိုဟ်၊ တလိၚ်ဒိုဟ်ကၠၚ် = အရပ်မျက်နှာကို အမှတ်မှားသည်။ မမှတ်မိဖြစ်သည်။ မျက်စိလည်သည်။ || “ညးမသုန်ကၠံကွဳဂှ် အာပဗၞိက် စိုပ်ပ္ဍဲတရၚ် ကန္တာဂှ်တုဲ တၠိၚ်အာဂၠံၚ် တၠိၚ်အာဒိုဟ်တုဲ လုကဴထပှ်တ္ၚဲ ဂေတ်ဂေၚ်တဴပ္ဍဲတရဴကန္တာဂှ်ရ။” (ဇ— ၄ဝ၅။ အစွောံ။) = “ငါးရာကုန်သော လှည်းကုန်သည်တို့သည် ကုန်သွယ်ရန်သွားစဉ် ကန္တာရသို့ရောက်၍ လမ်းကိုလည်းကောင်း အရပ်မျက်နှာကိုလည်းကောင်း မမှတ်မိ မျက်စိလည်သည် ဖြစ်၍ ခုနစ်ရက်ပတ်လုံး ကန္တာရခရီး­ တဝဲလည်လည်ဖြစ်၍ သွားကုန်၏။” || “အဲဗ္ၜူဒၟံၚ်ရုပ်ဒေံ ဗြဴတုဲ ဒိုဟ်ကၠၚ်အဲကလိၚ်အာတုဲရ။” (ဇ—၅၃၁။ အစွောံ။) = “ချစ်နှမ၏ရုပ်အဆင်း­ ယစ်မူးသည်ဖြစ်၍ မျက်စိလည်၍ အရပ်မျက်နှာကို ငါအမှတ်မှားခဲ့ရပြီ။” || “လၟတလိၚ်အာဂြိုပ်။” = “မုဆိုးသည် တော­ မျက်စိလည်လမ်းမှားဖြစ်သည်။”')
,(5413,3,4,'မိမိ၏အရည်အချင်း အစွမ်းအစပမာဏကို ထင်မှတ်မှားသည်၊ မသိဖြစ်သည်။ မိမိကိုယ်ကို အထင်ကြီးလွန်းသည်။','“(ကၠဵုဂြိုပ်သမၠီုဂှ်) ဇၞော်စိုတ်သၠုၚ်မာန် တ လိၚ်ဗၞတ်တုဲ တိုၚ်ပ္တောအ်ဇကုကဵုခေသရာသဳဟဨကရာတ်သတ်—။”(ဇ—၁၄၃။ အစွောံ။) = “မြေခွေးမိုက်သည် မိမိ၏အစွမ်းပမာဏကို ထင်မှတ်မှား၍ စိတ်ကြီးဝင်မာနတက်ကာ ကေသရာဇာ ခြင်္သေ့မင်းနှင့် တုနှိုင်း၏။”')
,(5414,3,4,'မြင်နေကျလူမဟုတ် မျက်နှာစိမ်းဖြစ်သည်။',NULL)
,(5415,3,4,'လူကိုမမှတ်မိဖြစ်သည်။ လူမှားသည်။','“ညံၚ်ရဴညးတီဒဒှ်ေဒၟံၚ်အဲကီု ညးကၠုၚ်ဟီု အရေဝ်ကဵုအဲ၊ အဲရောဟွံတီညး၊ ညးတလိၚ်အာမၞိဟ်ဟာဟွံတီရ။” = “ကျွန်တော်နှင့်သိကျွမ်းရင်း နှီးနေသကဲ့သို့ ကျွန်တော့်ကို သူစကားလာပြောသည်။ ကျွန်တော်လည်း သူ့ကိုမသိပါ။ သူလူ များမှားနေသလား။”')
,(5416,3,1,'‘တၠုၚ်’ ရှု။',NULL)
,(5417,3,1,'ပြည်တောင်း။','စှ်တြဴတလတ်မွဲန = ဆယ့်ခြောက်ပြည်တစ်တင်း။')
,(5418,3,4,'‘ကလိတ်’ ရှု။',NULL)
,(5419,3,4,'လုယက်ဖျက်ဆီးသည်။ လုယက်သောင်းကျန်းသည်။','“ယြဴသၟိၚ်မွဲ ဟိုတ်မာဲ တဴပ္ဍဲဓဝ်သၟိၚ်စှ်ပြကာမ္ဂး ကမၠတ်သပုန်ဒမၠမတာ မၞိဟ်လီလှေက်တလေတ်ဂဗဝ်စတံဂှ်ဂၠိုၚ် ဍုၚ်ကွာန် ရးကးတံဂှ် ကတဴကတာန်ကၞုက်ကၞာဲ လီုလာ်ပြးဇး—။” (ဇ—၅၂ဝ။ အစွောံ။) = “အကြင်မင်းသည် တရားမစောင့်သည်ရှိသော် သူခိုး၊ ဒမြ၊ သူပုန်၊ လူဆိုးအစရှိသည့် လုယက်ဖျက်ဆီးသူ တို့သည်များ၍ ပြည်ရွာဇနပုဒ်တို့သည် ဆူပူပျက်စီးပြိုကွဲရကုန်၏။”')
,(5420,3,1,'ပလွေ။',NULL)
,(5421,3,4,'လိမ်လည်သည်။ လိမ်ညာသည်။ မုသားဆိုသည်။','“လဟီုမွဲ သၟိက်ဗလးဒဒိုက် ညး ၜိုန်တလန် ဟွံဒှ်သရၚ်ပါပ်။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “ဘေးဒုက္ခမှ လွတ်စေခြင်းငှာပြော သော အကြင်စကားသည် လိမ်ညာလှည့်စားသော်ငြားလည်း အကုသိုလ်မမြောက်။”')
,(5421,3,1,'လိမ်လည်ခြင်း။ လှည့်စားခြင်း။ မာယာ။','“အဲညာတ်စကာဒၞေၚ်မတ် ဗက်ဗ္ဒဴကၠေံကောန်တုဲ ပဗတ်ဟွံ တီသွံ။ တလန်ညးတ္ကအ်ပန်အောန်အာ တလန်တၠအဲဝွံ ဂၠိုၚ်သန်သွံဝေသန္တဝ်” သာ်ဝွံဗမၞး(ဇူဇက) တ္ၜေဟ်ဗောဓိသတ်ရ။ (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “အိုဝေသန္တရာ၊ မျက်ခုံးဖြင့် သၚ်အမှတ် သညာပေး၍ သင့်ကလေးတို့အား ထွက်ပြေးခိုင်းသည်ကို ငါမြင်နေပါလျက်နှင့် သၚ်မသိသလို ဟန်ဆောင်နေပါလား။ လေးကျွန်းသူတို့၏ လှည့်စားခြင်းမာယာသည် နည်းသေး၏။ သင်၏ လှည့်စားခြင်းမာယာကား များလေစွ” ဟုဇူဇကာပုဏ္ဏားဆို၏။ || ‘တမုန်တလန်’၊ ‘တနိက်တလန်’ (ကြိ) တို့လည်းရှု။')
,(5422,3,4,'မောင်းတီးသည်။',NULL)
,(5423,3,4,'(ရေတွင်) နှစ်သည်။','“ယွံသဟာဲပိုဲကျာံ၊ မူပမတလီုဖျေံအဲရော” သၟိၚ်ကၞုဲ ဂး။ (ဇ—၂ဝ၈။ အစွောံ။) = “အဆွေမိကျောင်း၊ အဘယ်ကြောင့်ငါ့ကို ရေ­နှစ်ဘိသနည်း” ဟု မျောက်မင်းမေး၏။ || “(သၟိၚ်ကုသသၟိက်ဂွံဗဵုပြဘာဝတဳတုဲ) စှ်ေအာပ္ဍဲလစဒကှ်ဂှ်တုဲ တလီုလဝ်ဇကုတုဲ နသၠဒကှ်ဂှ် ဂြောပ်ကၠေံက္ဍိုပ်တုဲ နဍောၚ်ဒကှ်သတီုခိုဟ်ဂေါဝ်ဂှ် ဂဒဵုလဝ်မုက်တုဲ ဒၟံၚ်တဴရ။” (ဇ—၅၃၁။ အစွောံ။) = “ကုသမင်းသည် ပဘာဝတီကိုမြင်လို၍ ရေကန်ထဲသို့ဆင်း၍ ကိုယ်ကို နှစ်လျက် ပဒုမ္မာကြာဖက်ဖြင့် ဦးခေါင်းကိုဆောင်း၍ ထူ၍လှသော ပဒုမ္မာကြာပွင့်ဖြင့် မျက်နှာကို ဖုံးကာလျက် နေနှင့်၏။” || “ပ္ဍဲသြၚ်လစဂှ် ဇွမၞိဟ်ဂှ် ညံၚ်ဍေံဟွံဂွံမံက်ဂှ် ဗှ်ေတလိုမ်ဗလိုက်ကၠေံ ညိ။” (ဇ—၄၁၆။ အစွောံ။) = “ထိုရေကန်­ ထိုလူသေအလောင်းကို ရေတွင်မပေါ်ရလေအောင် သၚ်နှစ်မြှုပ်ပစ်လေလော့။”')
,(5424,3,4,'၁။ (ဆံပင်) ဖြေချသည်။ ဖားလျားချသည်။','“သၟတ်ဗြဴဂှ် ဟုံဍာ်ကြဴက္ဍိုပ်တုဲ တၞဟ်နသကှ်သော်ဂှ် တလာဲလဝ်သော်ရ။” = “ထိုသူငယ်မသည် ရေချိုးခေါင်းလျှော်ပြီး၍ ဆံ ပင်ကိုခြောက်စေရန် ဖားလျားချထားသည်။”')
,(5424,3,4,'၂။ တွဲလျားချသည်။ တွဲလျားကျသည်။ တွဲလျား ဆွဲသည်။','“ပ္ဍဲကၞာၚ်ဆုဂှ် ကၞုဲဂ္ဇအ်ဒၟံၚ်ရ။ တလာဲဖျေံဇကုတုဲ ညံၚ်ရဴမပ္တုံဖျေံဇကုကီုပ—။” (ဇ— ၁၇၄။ အစွောံ။) = “(မျောက်သည်) သစ်ခက်­ထိုၚ်ပြီးလျှင် တွဲလျားဆွဲလျက် သက်ဘိသကဲ့သို့ ပြု၍—။” (ညောင်ကန်) || “(မၞိဟ်ဗြဴမ္ဂးဂှ်) မၞုံကဵုတှ်မတလာဲ—။” (ဇ—၂၁၉။ အစွောံ။) = “မိန်းမတို့မည်သည် တွဲလျားကျသောရင်သားရှိ၏။”')
,(5424,3,4,'၃။ အလေးချိန်များသောကြောင့် အောက်သို့ ညွတ်ကျသည်။','“(တၞံမုက်)မွဲကၞာၚ်ဂှ် သတ်ဍေံဂၠိုၚ်တုဲ တလာဲစှ်ေကၠုၚ်ရ။” (ဇ—၁၇၇။ အစွောံ။) = “တည်ပင်၏အကိုင်းတစ်ခုသည် အသီးလေးခြင်းကြောင့် အောက်သို့ညွတ်ကျလာ၏။” || ‘ကလာဲ’ ဟုလည်း အချို့ရေးသည်။')
,(5425,3,1,'ဆီးဖြူပင်။ ဆီးဖြူသီး။ (ပါဠိ—အာမလက)',NULL)
,(5425,3,4,'ကြွေကျသည်။ ထွက်ကျသည်။','“ဗြဴဍိက်ညး အာဂၠာဲအှ်ော သၠးကောန်တုဲ သုက်ဍေံတလုဲအာ။” (ဇ—၄၁။ အစွောံ) = “ထင်းရှာထွက်သော ကျွန်မသည် သားဖွား၍ အချင်းကြွေကျသွားသည်။”')
,(5426,3,4,'‘ကလှ်’ ရှု။',NULL)
,(5427,3,4,'မိုမောက်မြင့်တက်သည်။ (?) (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ ဒု။ ၅ဝ၆။ စန္ဒိမာမဟာ ထေရ်။)',NULL)
,(5428,3,4,'၁။ (အပေါက်ဖြစ်အောင်) ဖောက်သည်။','“တြုံကမၠတ်ဂှ် သၟိၚ်ကဵုပ္တိုန်ဆုစ ရံၚ်တုဲ တလိုဟ်ကၠေံအတ္တဘဴဍေံရ။” (ဇ—၁၄၇။ အစွောံ။) = “မင်းသည် ထိုခိုးသူယောကျာ်းအား တံကျင်လျှိုစေ၍ ၄င်း၏ခန္ဓာကိုယ်ကို တံကျင်ဖြင့် ထွင်းဖောက်စေသည်။”')
,(5428,3,4,'၂။ ဖြုတ်သည်။ ချွတ်သည်။','တလိုဟ်ကွဳ = လှည်းကိုချွတ်သည်။ လှည်းကိုဖြုတ်သည်။ || “ဗောဓိသတ် တလိုဟ်လဝ်ကွဳ ဒီုဒၟံၚ်တုဲ—။” (ဇ—၁၉၄။ အစွောံ။) = “ဘုရားလောင်းသည် လှည်းကိုချွတ်၍ နားနေ၏။”')
,(5428,3,4,'၃။ (သေနတ်စသည်) မောင်းပြုတ်၍ ပေါက်ထွက်သည်။','“သေနတ်တလိုဟ်အာ ရ။” = “သေနတ်မောင်းပြုတ်၍ ကျည်ဆံပေါက်ထွက်သွားသည်။” || “ကောန်ဍေၚ်တၠိုဟ်စှ်ေအာ ရ။” = “ခလုတ်ပြုတ်ကျသွားသည်။”')
,(5428,3,4,'၄။ (မျက်စိ)မှိတ်ကျသည်။ အိပ်ခြင်းသို့ကပ်သည်။','“ဟိုတ်ဒုဟ်သရာံပါပ် မဂစိုတ်ကၠေံသၟိၚ်မဂှ် သၟိၚ်အဇာတသတြု တိက်လှိၚ်ဟွံသိုက်သက်က်ရ။ ပ္ဍဲ မတ်မတၠိုဟ်စှ်ေဂှ်ဗက် နိမိတ်နရက်တံဂှ် ကၠုၚ်ပြာကတ်ရ။” (ဇ—၅၃ဝ။ အစွောံ။) = “အဖကို သတ်မိသော မကောင်းမှုကံကြောင့် အဇာတသတ်မင်းသည် ချမ်းသာစွာ လုံးဝမအိပ်စက်ရ။ မျက်စိမှိတ်ကျသည်နှင့် (အိပ်ခြင်းသို့ကပ်သည်နှင့်) ငရဲနိမိတ်တို့သည် ထင်ရှားလာကုန်၏။”')
,(5429,3,4,'(လျှာ)ထုတ်သည်။','“လတာ်လေဝ် တလေအ်ပ္တိတ်ကၠေံရ။” (ဇ—၁၆။ အစွောံ။) = “(သမင်သည်) လျှာကိုလည်း ထုတ်လျက်ထား၏။” || ‘ကလေအ်’ ရှု။')
,(5430,3,4,'‘ကလောအ်’ ရှု။',NULL)
,(5431,3,1,'အကျယ်အဝန်း။',NULL)
,(5432,3,4,'‘ကလံက်’ ရှု။',NULL)
,(5433,3,4,'လံထားသည်။','တဝါလဝ်ဂၠဴ = နွားကို အစာစားစေရန် (စားကျက်တွင်) လံထားသည်။ || “မာၚ်ဗၠာဲဂမာဂၠဴမွဲ သတိက်လှိၚ်အာ ဂၠဴတဝါလဝ်၊ နူတေံကမၠတ်မွဲကၠုၚ် တီမာၚ်ဗၠာဲတၠဂၠဴမလှိၚ် ကမၠတ်ကၠတ်ဏာဂၠဴရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “တစ်ယောက်သောနွားကျောင်းလုလင်သည် နွားကိုလံထားကာ အိပ်ပျော်သွား၏။ တစ်ယောက်သောသူခိုးသည် ထိုမှလာ၍ နွားရှင်လုလင်အိပ် ပျော်သည်ကိုသိ၍ နွားကိုခိုးယူသွား၏။”')
,(5434,3,1,'လမ်းလျှောက်ဟန်။ လမ်းလျှောက်ခြင်း။','“တဝါ်သၟတ်ဗြဴဂှ် ရံၚ်စခိုဟ်ကွေံကွေံရ။” = “ထိုသူငယ်မ၏လမ်းလျှောက်ဟန်သည် ကြည့်၍အလွန်ကောင်းသည်။”')
,(5435,3,4,'(လှေ၊ သၚ်္ဘော) ဖြောင့်တန်းစွာ ခုတ်မောင်းသွားသည်။','“က္ၜၚ်တဝန်တိတ်အာ ထပှ် တ္ၚဲ စိုပ်ဒေါဝ်မှာသၟိတ်—။” (ဇ—၁ဝ၄။ အစွောံ။) = “သၚ်္ဘောသည် ဖြောင့်တန်းစွာထွက်ခွါသွား ရာ ခုနစ်ရက်တွင် သမုဒ္ဒရာလယ်သို့ရောက်၏။”')
,(5436,3,1,'၁။ အဟော။ ဟောကြားချက်။','တဝှ်ဓဝ် = ဟောကြားသောတရား။ || “တဝှ်ဓဝ်တိပိုန် သာရိပိုတ် မတွံကဵုမှာမုဂ္ဂလာန်—။” (ဇ—၁၅၃။ အစွောံ။) = “အရှင်သာရိပုတ္တရာ၏ အရှင် မောဂ္ဂလာန်အား ဟောကြားသောတရား—။”')
,(5436,3,1,'၂။ အကြောင်း။ ဖြစ်ကြောင်း။','“ပ္ဍဲဒြာဲသာခဂှ် ဟွံဂွံအခေါၚ်တုဲ ဒြာဲဗြဴဂှ် အတိုၚ်တဝှ်အိုဿီုဂှ် အာပ္တီဗောဓိသတ်(ဒြာဲနိဂြောဓ)ရ။” (ဇ—၁၂။ အစွောံ။) = “ထိုသမင်မသည် သာခသမင်ထံ­ အခွင့်မရ၍ အကြောင်းအလုံးစုံကို ဘုရားလောင်း နိဂြောဓသမင်အား သွား၍ပြောပြ၏။”')
,(5437,3,1,'မြတ်စွာဘုရား၏ နှုတ်ကပါဋ္ဌ်တော်မှ ဟောကြားတော်မူသောတရား။','“ကွးတဳတံဂှ် ဂွံမိၚ်ဓဝ်တဝှ်ပါၚ်ကျာ်တြဲတုဲ ပလီုကၠေံသရဏ ပ္ဍဲတဳတေံတုဲ ဂိုၚ်ကေတ်သရဏဂမနပိ ပ္ဍဲဇရေၚ်ကျာ်တြဲရ။” (ဇ—၁။ အစွောံ။) = “တိတ္ထိတို့၏တပည့်တို့သည် မြတ်စွာဘုရား၏နှုတ်က ပါဋ္ဌ်တော်မှ တရားတော်ကိုနာရ၍ တိတ္ထိတို့၏သရဏဂုံကို ဖျက်ကုန်၍ မြတ်စွာဘုရားအထံမှ သရဏဂုံကို ယူကုန်၏။”')
,(5438,3,1,'သစ္စာဆိုခြင်း။ သစ္စာပြုခြင်း။ ဆိုထားသောသစ္စာစကား။','ပတဝှ်စၟတ် = သစ္စာဆိုသည်။ သစ္စာပြုသည်။ မၚ်မွဲတဝှ်စၟတ်သစ္စ = ဆိုထားသောသစ္စာစကားကို စောင့်စည်းသည်။')
,(5439,3,1,'လှော်တက်။',NULL)
,(5440,3,1,'အမွေး။','တသော်ကအ် = လည်ဆံမွေး။ || တသော်ကၞေၚ်မတ်၊ တသော်ဒၞေၚ်မတ် = မျက်ခုံးမွေး။ || တသော်ဗ္ၜေံ၊ တသော်ဗ္ၜေံဂလာ = သိုးမွေး။')
,(5441,3,1,'သားမွေး။ သိုးမွေး။','ပလောအ်တသော်သတ် = သားမွေးအင်္ကျီ။')
,(5442,3,1,'ပွေးအရေပြားရောဂါ။',NULL)
,(5443,3,1,'ပွေးဝဲယားနား။',NULL)
,(5444,3,1,'ချမ်းသာခြင်း။ စည်းစိမ်ချမ်းသာ။','တသိုက်မၞိဟ် = လူ့စည်းစိမ်။ || တသိုက်သွဝ် = နတ်စည်းစိမ်။ || တသိုက်ၛာန် = ဈာန်ချမ်းသာ။ || တသိုက်လောကဳ = လောကီချမ်းသာ။')
,(5445,3,5,'ချမ်းသာစွာ။ ချမ်းသာသဖြင့်။ သက်သောင့်သက်သာ။','“(ဇာဒိသိုၚ်စဖျုန်ဖဲတုဲ) လုပ်အာဂိုဟ်တၟံ သတိက်ဒၟံၚ်နတသိုက်ရ။” (ဇ—၁၄၃။ အစွောံ။) = “ခြင်္သေ့သည် အသားကို ဝအောင်စားပြီးလျှင် ဂူသို့ဝင်၍ ချမ်းသာစွာအိပ်၏။” || “(ဗောဓိသတ်) ကာလမဗၠးနူဂၠံဂဝ်ဂှ် နတသိုက်ဟေၚ် မဂွံဒှ်မၞိဟ်။” (ဇ—၁၈၁။ အစွောံ။) = “ဘုရားလောင်းသည် အမိဝမ်းအိမ်မှ လွတ်သောကာလ­ ချမ်းသာသဖြင့် ဖွားမြင်၏။”')
,(5446,3,1,'စိတ်ချမ်းသာခြင်း။','“ပိုဲဖေက်ကၠဂှ်တုဲ တသိုက်စိုတ်ပိုဲ ဟၟဲသက်က်ရ။ ဟိုတ်ဂှ်တုဲ ပိုဲဇြာဲရောၚ်” ကၠိက်တံဂှ်ဂး။ (ဇ—၂၈၃။ အစွောံ။) = “ထိုကျားကိုကြောက်သဖြင့် အကျွန်ုပ်တို့­ စိတ်၏ငြိမ်းအေးချမ်းသာခြင်းသည် မရှိ။ ထို့ကြောင့် အကျွန်ုပ်တို့သည် ပိန်ကုန်၏” ဟုတော ဝက်များဆို၏။')
,(5447,3,1,'ခြေထိတ်။ ထိတ်တုံး။','“ကမၠတ်မဂၠိုၚ် ညးရပ်နၚ် — ညးအာဒက်လဝ် နဒွက်တသိၚ် နဒွက်ဇုက် နဒွက်ဇရေဟ် ညးမဒက်လဝ်ဗွဲမဗိုန်ရ။” (ဇ—၂ဝ၁။ အစွောံ။) = “များစွာသောခိုးသူတို့အား ဖမ်းဆီးရမိပြီးလျှင် ခြေထိတ်အနှောင် အဖွဲ့၊ ကြိုးအနှောင်အဖွဲ့၊ သံခြေချင်းအနှောင်အဖွဲ့တို့ဖြင့် မြဲစွာနှောင်ဖွဲ့ထား၏။”')
,(5448,3,1,'လုသည်။ လုယက်သည်။ အတင်းအဓမ္မပြုသည်။','“ယွံတဳလမၞုံပိုန်၊ ပိုဲဟီုအကြီုခမဳၜါ မတသိုၚ်ဘာဂှ်ရောၚ်အဴ” ခမဳဂမၠိုၚ်ဂး။ (ဇ—၂၉၈။ အစွောံ။) = “ဘုန်းတော်ကြီးသောအရှင်ဘုရား၊ တပည့်တော်တို့သည် ထိုရဟန်းနှစ်ယောက်တို့ ကျောင်းလုကြသည့်အကြောင်းကို ပြောဆို ကြပါကုန်၏။” || “ယွံတၠညး၊ ကမၠတ်ဇၞော်မွဲဂှ် ဍေံတသိုၚ်ပၠံၚ်စပိုဲဍိက်အဴ။ ကမၠတ်ဂှ် သၟိက်ကဵုတၠညး ရပ်ဍေံညိအဴ” ညးဍုၚ်ဂမၠိုၚ်ဂး။ (ဇ—၃၁၈။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ တယောက်သော ခိုးသူကြီးသည် မြို့ကိုလုယက်၏။ ထိုခိုးသူကြီးကို ဖမ်းစေလော့” ဟု မြို့သူတို့သည် လျှောက် ကုန်၏။ (ညောင်ကန်) || “ပကောံကေတ်ဗဵုလဗးတုဲ ဇက်ပ္ၚောအ်အာ တသိုၚ်ကေတ်ကၟိန်ဍုၚ်ပၠန် ရ။” (ဇ—၄၆၇။ အစွောံ။) = “ရဲမက်ဗိုလ်ပါတို့စုရုံး၍ ဦးတည်ချီတက်သွားကာ တိုင်းပြည်ကို တိုက်ခိုက်လုယူပြန်၏။” ||   “ကၠဂှ်ချိုတ်အာရဂးတုဲ ကၠိက်ဂမၠိုၚ်မိပ်စိုတ်တုဲ တသိုၚ်စဂြိုဟ်ဖျုန်ကၠဂှ် အိုတ်သ္အးအာရ။” (ဇ—၄၉၂။ အစွောံ။) = “ထိုကျားသေလေပြီဟု တောဝက်တို့သည် ဝမ်းသာကုန်၍ ကျားသားကို အလုအယက်စားကြကုန်ရာ ကျားသားမကြွင်းမကျန် ကုန်စင်သွားလေ၏။” || ‘တသိုၚ်ပၠံၚ်ကေတ်သမ္ဘာညး။’ (ဇ—၅၁၅။ အစွောံ။) = ‘သူတစ်ပါးမယားကို အဓမ္မလုယူသည်။’ || ‘ဒသိုၚ်’ ဟုလည်းရေးသည်။')
,(5449,3,4,'(သူနိုင်ငါနိုင်) တရားပြိုင်သည်။','“တၠအမှုၜါလ္ပာ်တအ်ဂှ် တသိုၚ်သၞောဝ်ရၚ် သ္ကအ်ရ။” = “နှစ်ဖက်သောအမှုသည်များ သူနိုင်ငါနိုင် တရားပြိုင်ကြ၏။”')
,(5450,3,4,'၁။ နိမ့်ကျသည်။ နိမ့်ရာသို့ရွှေ့ကျသည်။','“ဒဵုလာ်တုဲ ဒၞာဲလ္ၚဵု တိတသိုတ်စှ်ေအာ ရ။” = “တောင်ပြိုပြီး အချို့နေရာတွင် မြေနိမ့်ကျသွားသည်။”')
,(5450,3,4,'၂။ ကောင်းရာမှဆိုးရာသို့ ရွေ့လျောသည်။','“ယြဴသၟိၚ်မွဲဟွံတဴပ္ဍဲဓဝ်ဂှ် — နူဋ္ဌာန်ဒၟံၚ်တသိုက်ဍုၚ်သွဝ်ဂှ် သၟိၚ်ဒးတသိုတ်အာ ရ။” (ဇ—၁၉၄။ အစွောံ။) = “တရားမစောင့်သောမင်းသည် နတ်ရွာစည်းစိမ်ဋ္ဌာနမှ ရွေ့လျှောရ၏။” (ညောင်ကန်) || “သၟိၚ်ဒၟံၚ်ပ္ဍဲသၞာမသၠုၚ်တုဲ ကတ်ကေတ်ကွတ်မန် ပ္ဍဲအစာမဒၟံၚ်ပ္ဍဲသၞာမသဝ် အိုဿီုညးၜါဂှ် တသိုတ်အာနူဒ္ဂေတ်ညးတမၠာတေံတုဲရ။” (ဇ—၃ဝ၉။ အစွောံ။) = “မင်းသည် မြင့်သောနေရာတွင်နေ၍ နိမ့်သောနေရာတွင်နေသော ဆရာ၏အထံ­ မန္တန်ကိုသင်ယူ၏။ အလုံးစုံသော ဤသူနှစ်ဦးတို့သည် ရှေးအစဉ်အလာတရားမှ ရွေ့လျော၏။” || “ပတွဵုနူကျအာဍုၚ် ပ္ဍဲ သၞာံခရေတ် ၁၇၅၇ ဂှ်တုဲ ဂကူမန်ဂှ် မဒးတသိုတ်သဝ်စှ်ေအာ ဒဒှ်ဂကူဟွံမွဲကဵုဍုၚ်မွဲရ။” = “ခရစ်နှစ် ၁၇၅၇ ခု နိုင်ငံကျဆုံးသွားသည်မှစ၍ မွန်လူမျိုးတို့သည် နိုင်ငံမဲ့လူမျိုးတစ်မျိုးအဖြစ်သို့ ရွေ့လျောနိမ့်ကျသွားရသည်။” || တသိုတ်အာနူသာသနာ = သာသနာမှ ရွေ့လျောသည်။ (ပါဠိ— စာဝနာဓိပ္ပါယ) || “(ယာံရအဲဒးဟီုဂလာန်မုသာမ္ဂး) နူဒဒှ်ဂမှဳဂှ် ကဵုဒးတသိုတ်အာတုဲ ကဵုဒးဒှ်ခရှ်တုဲ ပ္ဍဲတမျောဝ်သ္ၚိကၟိန်ဂှ် ကဵုအဲဒးပကာဂစိုတ်ညိ” သာ်ဝွံဗောဓိသတ်ဒုၚ်သွဴရ။ (ဇ—၄၈၈။ အစွောံ။) = “ငါသည် မုသားစကားကို အကယ်၍ဆိုခဲ့ငြားအံ့၊ ရဟန်းအဖြစ်မှ ရွေ့လျောရသည်ဖြစ်၍ လူဝတ် ကြောင်ဖြစ်ရ၍ အိမ်ရာထောင်သောလူ၏ဘောင်­ သေရပါစေသတည်း” ဟု ဘုရားလောင်းကျိန် ဆို၏။')
,(5450,3,4,'၃။ ဆုတ်နစ်သည်။ တွန့်ဆုတ်သည်။','‘စိၚ်ဒယှ်မၞုံဂမံၚ် မဟွံဂွံတသိုတ်။’ (ဇ—၅၃၁။ အစွောံ။) = ‘မတွန့်ဆုတ်သော ရဲရင့်ခြင်းနှင့်ပြည့်စုံသောဆင်ကျော်။’ || ‘ညံၚ်စိၚ်ဗြဴ နကဵုစရာၚ် ညးမပကတ်ဝေတ်လဝ်တုဲ မဟွံဂွံဆုတ်တသိုတ် ပ္ဍဲဋ္ဌာန်စၞေဟ်ဂှ်ကီု။’ (ဇ—၄၄၆။ အစွောံ။) = ‘ချွန်းဖြင့်လေ့ကျင့်ဆုံးမထားအပ်သောဆင်မသည် စစ်မြေပြင်­ မဆုတ်မနစ်သကဲ့သို့။’')
,(5450,3,4,'၄။ ကျွတ်သည်။ ပြုတ်သည်။','“ရပ်ကၞိရစွံစိုတ်တုဲ ဗ္ဂဲဂှ်စလာ်ကၠုၚ် သြိုဟ်ဒွံဒးဂိုဟ်ဂှ် ဒှ်အာၜါလွး ဂဍောၚ် မတ်ညံၚ်တသိုတ်တိတ် အိုတ်လမျီုရ။” (ဇ—၁၃၇။ အစွောံ။) = “ကြွက်အားဖမ်းအံ့ဟု ကြောင်သည်ပြေးခုန်လာရာ ရၚ်ဖြင့်ဖလ်ဂူကိုခတ်မိ၍ ရၚ်နှစ်ခြမ်းကွဲကာ မျက်လုံးပြုတ်ထွက်ဘိသကဲ့သို့ ဖြစ်၍ အသက်ကုန်၏။”')
,(5451,3,4,'တိုးလျှိုးတောင်းပန်သည်။ (?)','“တလဂုန်လ္ပဂစိုတ်ကောန်အဲဍိက်ဗြဴညိ အဴ” ဂစေံတၞောတ်ဗြဴ လ္ၚောဝ်ဟီုတသောန်တသဝ်ဒၟံၚ် ကဵုစိၚ်ဒမြိုဟ်ဂှ်ရ။ (ဇ—၃၅၇။ အစွောံ။) = “ကျွန်တော်မ၏သားငယ်တို့ကို ကျေးဇူးရှင်မသတ်ပါလင့်” ဟု နှံစုတ်ငှက်မသည် ထိုကြမ်းကြုတ် သောဆင်အား ရှိခိုးလျက် တိုးလျှိုးတောင်းပန်ရှာ၏။')
,(5452,3,1,'အနား။ အစွန်း။ အမြိတ်။',NULL)
,(5453,3,4,'ညည်းညူသည်။','‘ကသဝ်’ (ကြိ)နှင့်အတူတူ။')
,(5454,3,4,'ဆင်ခြေလျှောသည်။','ဋ္ဌာန်တသောဝ်ဝါတ် = ဆင်ခြေလျှောဖြစ်၍ သွားလာရန် ခက်ခဲသောနေရာ။ || “ဂစေံဗြဴဂှ် ဂၠာဲစစၞပ္ဍဲဂၠံၚ်ကွဳ ပ္ဍဲဋ္ဌာန်တသောဝ်ဝါတ်ဂှ် ကွဳကၠုၚ်ဒဴဟွံဂတာပ် ကွဳ လိုန်ဒးချိုတ်အာဒၞာဲဂှ်ရ။” (ဇ—၁၁၅။ အစွောံ။) = “ထိုငှက်မသည် လှည်းလမ်းပေါ် ဆင်ခြေလျှော၍ သွားလာရန်ခက်ခဲသောနေရာတွင် အစာရှာစားရာ လှည်းလာသည်ကို ရှောင်ရန်မမီဘဲ လှည်းနင်း၍ ထိုနေရာ­ပင် သေလေ၏။”')
,(5455,3,4,'၁။ ပြန့်ကြဲသည်။ အနှံ့ပြန့်သည်။','“(စိၚ်ဇေဟ်စုတ်ကၠဵုဂှ်) ကြုတ်တသဵုတိတ်အာရ။” (ဇ—၁၄၃။ အစွောံ။) = “ဆင်သည် မြေခွေးကို ဆောင့်နင်းလိုက်ရာ ထိုခွေး၏အူများ ပြန့်ကြဲ ထွက်ကုန်၏။”')
,(5455,3,4,'၂။ စုရုံးသည်။ စုအုံသည်။ အလုံးအရင်းနှင့်လာသည်။','“ညံၚ်စရာဲအိန်သွဝ်ၜါဂှ် သီုအသေဝ်အဟာန်ဗဵုပၞာန် ဇက်ထပ်ကၠုၚ်ဟွံတီဗၞတ်တွဵု ဇက်သကိုဟ်တသဵုကၠုၚ်ဂှ် ညးသၟိၚ်ဂှ်ရော ကောန်။” (ဇ—၅၃၂။ အစွောံ။) = “ချစ်သား၊ သိကြားမင်း၏အသရေကဲ့သို့ စစ်သည်ဗိုလ်ပါအ ခြံအရံများနှင့်တကွ မရေမတွက်နိုင်အောင် အထပ်ထပ် အလုံးအရင်းနှင့် ချီတက်လာသောမင်းသည်ကား အဘယ်သူပါနည်း။”')
,(5456,3,4,'(ပါးစပ်၊ နှာခေါင်းစသည်မှ) မှုတ်ထုတ်သည်။','‘ဇြုံဇာတ်တသိုဟ် ပ္တိတ်ဂျိ။’ = ‘မြွေဟောက်သည် အဆိပ်ကို မှုတ်ထုတ်သည်။’ || “သၟိၚ်နာ်တၠဣဓိတေံပၞတ်တုဲ တသောဟ်ပ္တိတ်ဒးကောန်ဗၞိက် ချိုတ်လေၚ်အိုတ်သ္အးအာရ။” (ဇ—၂၅၆။ အစွောံ။) = “တန်ခိုးရှင်န ဂါးမင်းက အမျက်ထွက်၍ နှာခေါင်းလေဖြင့်မှုတ်၍ ကုန်သည်တို့သည် အားလုံးသေကြေပျက်စီး ကုန်၏။” || “(ကုကောန်ၚာ်တံဂှ်) နကျာမုဟ်အဲ တသိုဟ်ပ္တိတ် ပၠေၚ်ကၠေံဍေံရဟာကော” နာ်ဒေံဂှ် ဂး။ (ဇ—၃ဝ၄။ အစွောံ။) = “နောင်တော်၊ ထိုသူငယ်တို့ကို အကျွန်ုပ်၏နှာခေါင်းလေဖြင့် မှုတ်ထုတ်၍ ပျက်စီးစေရအံ့လော” ဟုညီနဂါးဆို၏။')
,(5457,3,4,'၁။ ဝမ်းနည်းပြီး ညည်းညူသည်။ သောကရောက်သည်။','“ပ္ဍဲကာလကျာ်တြဲ အရဳယျက္တဵုဒှ်ဂှ် သတ္တအ်မဒးဒိုက်ဒိန်ကာဲကၞာဲ စံၚ်တူတသိုဟ်တဟးဟွံမွဲရ။” (အဓါန်မသုန် / အစွောံ) = “အရိယျမေတ္တေယျမြတ်စွာဘုရား ပွင့်တော်မူသောကာလ­ သတ္တဝါအပေါင်းတို့သည် ဆင်းရဲ ခြင်း၊ ပူပန်ခြင်း၊ သောကရောက်ခြင်း မရှိကြကုန်။”')
,(5457,3,4,'၂။ အခြေအတၚ်ဆွေးနွေးသည်။',NULL)
,(5458,3,4,'နှပ်ညှစ်သည်။',NULL)
